  // News Analytics Endpoint - Smart statistics and insights


  // Quick disconnect endpoint (called via beacon on tab close)
  // نقطة اتصال سريعة للإغلاق (تُستدعى عند إغلاق التبويب)
  app.post("/api/admin/moderator/disconnect", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user?.id;
      if (userId) {
        await storage.setModeratorOffline(userId);
        console.log(`[Disconnect] User ${userId} marked offline via disconnect beacon`);
      }
      res.status(204).end();
    } catch (error) {
      // Silent fail - do not block the page close
      res.status(204).end();
    }
  });

  // News Analytics Endpoint - Smart statistics and insights
  // Get current user
  app.get("/api/auth/user", async (req: any, res) => {
    try {
      if (!req.isAuthenticated() || !req.user?.id) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const userId = req.user.id;
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      // Get all user's roles from RBAC system, fallback to user.role from users table
      const userRolesResult = await db
        .select({ roleName: roles.name, roleNameAr: roles.nameAr })
        .from(userRoles)
        .innerJoin(roles, eq(userRoles.roleId, roles.id))
        .where(eq(userRoles.userId, userId));

      // Get all roles as array
      const rolesArray = userRolesResult.map(r => r.roleName);

      // Prefer the first non-reader RBAC role so writers/reporters/editors
      // surface their actual title instead of getting overridden by a
      // stray "reader" assignment (matches Mobile API logic in
      // mobileApiRoutes.ts:buildUserRolePayload).
      const nonReaderRole = userRolesResult.find(
        (r) => r.roleName && r.roleName !== "reader",
      );

      // For backward compatibility, keep 'role' as first role, add 'roles' array
      const role = nonReaderRole?.roleName
        || rolesArray[0]
        || user.role
        || "reader";
      const allRoles = rolesArray.length > 0
        ? rolesArray
        : [user.role || "reader"];
      // `roleLabel` is the Arabic display name pulled straight from the
      // `roles` table — single source of truth, no client-side
      // translation map needed. Falls back to the job title (e.g.
      // "كاتب رأي في علم النفس والمجتمع") and finally a hard-coded
      // "قارئ" so writers without an explicit job title still show
      // something meaningful.
      const roleLabel = nonReaderRole?.roleNameAr
        || userRolesResult[0]?.roleNameAr
        || user.jobTitle
        || "قارئ";

      // Get user permissions from RBAC system (includes permission overrides)
      // استخدام الدالة الموحدة التي تشمل الاستثناءات الشخصية
      const dbPermissions = await getUserPermissions(userId);
      
      // Also derive permissions from role-based mapping (for permissions defined in code but not yet in DB)
      const { getPermissionsForRoles } = await import("@shared/rbac-constants");
      const roleBasedPermissions = getPermissionsForRoles(allRoles);
      
      // Merge both sources
      const permissionsArray = [...new Set([...dbPermissions, ...roleBasedPermissions])];

      // SECURITY: Never send passwordHash to client
      const { passwordHash, twoFactorSecret, ...safeUser } = user;
      res.json({
        ...safeUser,
        role,
        roles: allRoles,
        roleLabel,
        permissions: permissionsArray,
      });
    } catch (error) {
      console.error("Error fetching user:", error);
      res.status(500).json({ message: "Failed to fetch user" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights

  app.patch("/api/auth/user", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;

      const parsed = updateUserSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          message: "بيانات غير صحيحة",
          errors: parsed.error.errors
        });
      }

      // firstName / lastName are write-once for integrity: once a
      // non-empty value exists on the row, the column is readonly. An
      // attacker briefly in control of an account could otherwise rename
      // it to impersonate a different commenter, turning the public
      // comments archive into a deniability laundromat. We silently drop
      // the name fields rather than 400-ing so legacy clients that always
      // post the full form don't break on save.
      const existing = await storage.getUser(userId);
      const data = { ...parsed.data };
      if (existing?.firstName && existing.firstName.trim().length > 0) {
        delete data.firstName;
      }
      if (existing?.lastName && existing.lastName.trim().length > 0) {
        delete data.lastName;
      }

      const user = await storage.updateUser(userId, data);
      res.json(user);
    } catch (error) {
      console.error("Error updating user:", error);
      res.status(500).json({ message: "فشل في تحديث البيانات" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights

  // Profile image upload endpoints (Reference: javascript_object_storage blueprint)
  app.post("/api/profile/image/upload", isAuthenticated, async (req: any, res) => {
    try {
      const objectStorageService = new ObjectStorageService();
      const uploadURL = await objectStorageService.getObjectEntityUploadURL();
      res.json({ uploadURL });
    } catch (error) {
      console.error("Error getting upload URL:", error);
      res.status(500).json({ message: "فشل في الحصول على رابط الرفع" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights

  app.put("/api/profile/image", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;

      if (!req.body.profileImageUrl) {
        return res.status(400).json({ message: "رابط الصورة مطلوب" });
      }

      console.log("[Profile Image] Upload URL received:", req.body.profileImageUrl);

      // If the URL is already a fully-qualified external URL (Cloudflare
      // Images via imagedelivery.net, or any other CDN), we skip the
      // Replit-sidecar-backed ACL step — there's nothing to ACL on an
      // external host, and trySetObjectEntityAclPolicy would call the
      // 127.0.0.1:1106 sidecar that doesn't exist on Railway.
      let objectPath: string;
      if (/^https?:\/\//.test(req.body.profileImageUrl)) {
        objectPath = req.body.profileImageUrl;
        console.log("[Profile Image] External URL — skipping ACL step");
      } else {
        const objectStorageService = new ObjectStorageService();
        objectPath = await objectStorageService.trySetObjectEntityAclPolicy(
          req.body.profileImageUrl,
          {
            owner: userId,
            visibility: "public",
          }
        );
        console.log("[Profile Image] Object path after ACL:", objectPath);
      }

      // Update user profile with the new image path
      const user = await storage.updateUser(userId, {
        profileImageUrl: objectPath
      });

      console.log("[Profile Image] User updated with new image:", user.profileImageUrl);

      res.json({ 
        success: true,
        profileImageUrl: objectPath,
        user
      });
    } catch (error) {
      console.error("Error updating profile image:", error);
      res.status(500).json({ message: "فشل في تحديث الصورة الشخصية" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights

  // ============================================================
  // MEDIA LIBRARY API ENDPOINTS
  // ============================================================

  // GET /api/media - List all media files with pagination, search, and filtering
  app.get("/api/media", isAuthenticated, requirePermission("media.view"), async (req: any, res) => {
    try {
      const {
        search,
        url,
        folder,
        folderId,
        category,
        isFavorite,
        since,
        page = 1,
        limit = 20,
      } = req.query;

      const pageNum = Math.max(1, parseInt(page as string, 10) || 1);
      // radix MUST be 10 (was 20 → "20" parsed as base-20 = 40, corrupting paging).
      const limitNum = Math.min(100, Math.max(1, parseInt(limit as string, 10) || 20));
      const offset = (pageNum - 1) * limitNum;

      // Build where conditions
      const conditions = [];
      
      // Filter by exact URL match (for finding media by URL)
      if (url) {
        conditions.push(eq(mediaFiles.url, url as string));
      }

      if (search) {
        conditions.push(
          or(
            ilike(mediaFiles.fileName, `%${search}%`),
            ilike(mediaFiles.title, `%${search}%`),
            ilike(mediaFiles.description, `%${search}%`)
          )
        );
      }

      // Support both folderId and folder parameters
      const sqlFolderFilter = (folderId || folder) as string | undefined;
      if (sqlFolderFilter) {
        conditions.push(eq(mediaFiles.folderId, sqlFolderFilter));
      }

      if (category) {
        conditions.push(eq(mediaFiles.category, category as string));
      }

      if (isFavorite !== undefined) {
        conditions.push(eq(mediaFiles.isFavorite, isFavorite === 'true'));
      }

      // The picker sends `since` (ISO) for recently-added assets (was ignored).
      if (since) {
        const sinceDate = new Date(since as string);
        if (!isNaN(sinceDate.getTime())) {
          conditions.push(gte(mediaFiles.createdAt, sinceDate));
        }
      }

      // Smart collection presets (Phase 1). `most_used` changes ordering (below);
      // usage is checked LIVE so "unused"/"most used" stay accurate (usageCount drifts).
      const collection = req.query.collection as string | undefined;
      const orderByMostUsed = collection === 'most_used';
      if (collection === 'favorites') {
        conditions.push(eq(mediaFiles.isFavorite, true));
      } else if (collection === 'no_alt') {
        conditions.push(sql`(${mediaFiles.altText} IS NULL OR ${mediaFiles.altText} = '')`);
      } else if (collection === 'unused') {
        conditions.push(sql`NOT EXISTS (SELECT 1 FROM ${articleMediaAssets} WHERE ${articleMediaAssets.mediaFileId} = ${mediaFiles.id})`);
        conditions.push(sql`NOT EXISTS (SELECT 1 FROM ${mediaUsageLog} WHERE ${mediaUsageLog.mediaId} = ${mediaFiles.id})`);
      } else if (collection === 'pending') {
        // Phase 2: images awaiting / failed AI analysis (not yet auto-tagged).
        conditions.push(eq(mediaFiles.type, 'image'));
        conditions.push(sql`(${mediaFiles.aiAnalysisStatus} IS NULL OR ${mediaFiles.aiAnalysisStatus} IN ('pending','failed'))`);
      } else if (collection === 'no_rights') {
        // Phase 6: images whose usage rights haven't been verified yet.
        conditions.push(eq(mediaFiles.type, 'image'));
        conditions.push(eq(mediaFiles.rightsVerified, false));
      }

      const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

      // Dedupe by URL + paginate in SQL (DISTINCT ON keeps the newest row per
      // URL; the outer query re-orders + LIMIT/OFFSET). Live usage is computed
      // ONLY for most_used so the default path stays cheap.
      const usageExpr = sql<number>`((SELECT count(*) FROM ${articleMediaAssets} WHERE ${articleMediaAssets.mediaFileId} = ${mediaFiles.id}) + (SELECT count(*) FROM ${mediaUsageLog} WHERE ${mediaUsageLog.mediaId} = ${mediaFiles.id}))`;
      const dedupSub = db
        .selectDistinctOn([mediaFiles.url], {
          id: mediaFiles.id,
          url: mediaFiles.url,
          createdAt: mediaFiles.createdAt,
          usage: orderByMostUsed ? usageExpr : sql<number>`0`,
        })
        .from(mediaFiles)
        .where(whereClause)
        .orderBy(mediaFiles.url, desc(mediaFiles.createdAt), desc(mediaFiles.id))
        .as("dedup");

      const pagedRows = await db
        .select({ id: dedupSub.id })
        .from(dedupSub)
        .orderBy(
          orderByMostUsed ? desc(dedupSub.usage) : desc(dedupSub.createdAt),
          desc(dedupSub.id),
        )
        .limit(limitNum)
        .offset(offset);

      const fileIds = pagedRows.map((r) => r.id);

      const [totalRow] = await db
        .select({ total: sql<number>`count(distinct ${mediaFiles.url})` })
        .from(mediaFiles)
        .where(whereClause);
      const total = Number(totalRow?.total) || 0;

      // Fetch full details for the deduplicated, paginated IDs
      let deduplicatedItems: any[] = [];
      if (fileIds.length > 0) {
        const items = await db
          .select({
            id: mediaFiles.id,
            fileName: mediaFiles.fileName,
            originalName: mediaFiles.originalName,
            folderId: mediaFiles.folderId,
            url: mediaFiles.url,
            thumbnailUrl: mediaFiles.thumbnailUrl,
            type: mediaFiles.type,
            mimeType: mediaFiles.mimeType,
            size: mediaFiles.size,
            width: mediaFiles.width,
            height: mediaFiles.height,
            title: mediaFiles.title,
            description: mediaFiles.description,
            altText: mediaFiles.altText,
            caption: mediaFiles.caption,
            keywords: mediaFiles.keywords,
            isFavorite: mediaFiles.isFavorite,
            category: mediaFiles.category,
            aiAnalysisStatus: mediaFiles.aiAnalysisStatus,
            aiQualityScore: mediaFiles.aiQualityScore,
            aiHasSensitiveContent: mediaFiles.aiHasSensitiveContent,
            isAiGenerated: mediaFiles.isAiGenerated,
            licenseType: mediaFiles.licenseType,
            creditText: mediaFiles.creditText,
            copyrightHolder: mediaFiles.copyrightHolder,
            rightsVerified: mediaFiles.rightsVerified,
            rightsNote: mediaFiles.rightsNote,
            usedIn: mediaFiles.usedIn,
            usageCount: mediaFiles.usageCount,
            uploadedBy: mediaFiles.uploadedBy,
            createdAt: mediaFiles.createdAt,
            updatedAt: mediaFiles.updatedAt,
            folder: mediaFolders,
            uploader: {
              id: users.id,
              email: users.email,
              firstName: users.firstName,
              lastName: users.lastName,
              profileImageUrl: users.profileImageUrl,
            },
          })
          .from(mediaFiles)
          .leftJoin(mediaFolders, eq(mediaFiles.folderId, mediaFolders.id))
          .leftJoin(users, eq(mediaFiles.uploadedBy, users.id))
          .where(inArray(mediaFiles.id, fileIds));

        // Preserve order from the CTE query (by created_at DESC, id DESC)
        const itemMap = new Map(items.map(item => [item.id, item]));
        deduplicatedItems = fileIds.map(id => itemMap.get(id)).filter(Boolean) as typeof items;
      }

      // Return files with appropriate URLs:
      // - Files with https:// URLs (public) use direct URL
      // - Files with gs:// URLs (private) use proxy URL
      // - Keep originalUrl for storage in articles
      const filesWithUrls = deduplicatedItems.map(item => {
        const displayUrl = item.url.startsWith('https://') 
          ? item.url 
          : `/api/media/proxy/${item.id}`;
        
        return {
          ...item,
          originalUrl: item.url, // Keep original URL from database (https:// or gs://)
          url: displayUrl, // Display URL for preview (https:// or /api/media/proxy/)
          proxyUrl: `/api/media/proxy/${item.id}`,
        };

      });

      const hasMore = pageNum * limitNum < total;
      res.json({
        files: filesWithUrls,
        total,
        page: pageNum,
        limit: limitNum,
        hasMore, // the picker's "load more" button depends on this flag
      });
    } catch (error) {
      console.error("Error fetching media files:", error);
      res.status(500).json({ message: "فشل في جلب ملفات الوسائط" });
    }
  });


  // POST /api/media/upload - Upload media file to GCS
  const mediaUpload = multer({
    storage: multer.memoryStorage(),
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB max
    },
    fileFilter: (req, file, cb) => {
      // GIF removed (security audit M8, 2026-05-11).
      const allowedTypes = [
        'image/jpeg',
        'image/jpg',
        'image/png',
        'image/webp',
      ];
      if (allowedTypes.includes(file.mimetype)) {
        cb(null, true);
      } else {
        cb(new Error('نوع الملف غير مسموح. الأنواع المسموحة: JPEG, PNG, WEBP'));
      }
    },
  });


  // NOTE: platform-wide generic image upload pipe (avatars, category/topic
  // images, rich editor, angle-writer topic images) — NOT just the media library.
  // Intentionally auth-only: angle writers and avatar uploaders have no media.*
  // permission, so do NOT add requirePermission("media.upload") — it'd break them.
  app.post("/api/media/upload", isAuthenticated, mediaUploadLimiter, mediaUpload.single('file'), async (req: any, res) => {
    try {
      const userId = req.user.id;

      if (!req.file) {
        return res.status(400).json({ message: "لم يتم اختيار ملف" });
      }

      // multer parses the Content-Disposition filename as Latin-1 per the
      // HTTP spec default. Browsers send UTF-8 bytes, so non-ASCII names
      // (Arabic etc.) arrive as mojibake like "ÙØ±Ø©" instead of "صورة".
      // Round-trip via Latin-1 to recover the UTF-8 string.
      if (req.file.originalname && /[À-ÿ]/.test(req.file.originalname)) {
        req.file.originalname = Buffer.from(req.file.originalname, 'latin1').toString('utf8');
      }

      // Verify the file's actual magic bytes match the claimed MIME
      // (security audit M1, 2026-05-11). multer's fileFilter only
      // trusts the client-declared header; sharp reads the real format.
      if (req.file.mimetype.startsWith('image/')) {
        const verify = await verifyImageMagicBytes(req.file.buffer, req.file.mimetype);
        if (!verify.ok) {
          console.warn("[Media Upload] Magic byte verification failed:", verify.reason);
          return res.status(400).json({ message: "نوع الملف لا يطابق محتواه الفعلي" });
        }
      }

      console.log("[Media Upload] File received:", {
        originalName: req.file.originalname,
        mimetype: req.file.mimetype,
        size: req.file.size,
      });

      // Generate unique filename with year/month structure
      const now = new Date();
      const year = now.getFullYear();
      const month = String(now.getMonth() + 1).padStart(2, '0');
      // Reject anything other than a plain alphanumeric extension
      // (security audit H2, 2026-05-11). originalname.split('.').pop()
      // could otherwise return "../foo" or a multi-segment path and
      // break out of uploads/media/.
      const rawExt = req.file.originalname.split('.').pop()?.toLowerCase() || 'jpg';
      const fileExtension = /^[a-z0-9]{1,5}$/.test(rawExt) ? rawExt : 'bin';
      const objectId = randomUUID();

      const objectPath = `uploads/media/${year}/${month}/${objectId}.${fileExtension}`;

      // Try Cloudflare Images first for image uploads. When CF succeeds we
      // skip GCS entirely — GCS is only reached for non-images, or as a
      // fallback when CF is not configured / failed.
      let cloudflareUrl: string | null = null;
      if (req.file.mimetype.startsWith('image/') && cloudflareImagesService.isCloudflareConfigured()) {
        console.log("[Media Upload] Cloudflare Images configured, attempting upload...");
        const cfResult = await cloudflareImagesService.uploadToCloudflare(
          req.file.buffer,
          req.file.originalname,
          { uploadedBy: userId.toString(), type: 'media' },
          req.file.mimetype
        );
        if (cfResult.success && cfResult.deliveryUrl) {
          cloudflareUrl = cfResult.deliveryUrl;
          console.log("[Media Upload] Cloudflare upload successful:", { url: cloudflareUrl, imageId: cfResult.imageId });
        } else {
          console.log("[Media Upload] Cloudflare upload failed, will try GCS fallback:", cfResult.error);
        }
      }

      // GCS path — used only when CF didn't claim the upload. Wrapped in
      // try/catch so a missing/misconfigured GCS doesn't kill the request
      // when CF already has the file.
      let storagePath: string;
      if (cloudflareUrl) {
        storagePath = cloudflareUrl;
        console.log("[Media Upload] Stored via Cloudflare, skipping GCS:", cloudflareUrl);
      } else {
        const privateObjectDir = process.env.PRIVATE_OBJECT_DIR || '';
        const parts = privateObjectDir.split('/').filter(Boolean);
        let bucketId: string | undefined;
        if (parts.length >= 2 && parts[0] === 'objects') {
          bucketId = parts[1];
        } else if (parts.length >= 1) {
          bucketId = parts[0];
        }

        if (!bucketId) {
          return res.status(500).json({
            message: "خدمة رفع الصور غير متاحة. المتغيرات الخاصة بـ Cloudflare Images أو PRIVATE_OBJECT_DIR غير مضبوطة.",
          });
        }

        try {
          const { objectStorageClient } = await import('./objectStorage');
          const bucket = objectStorageClient.bucket(bucketId);
          const file = bucket.file(objectPath);

          await file.save(req.file.buffer, {
            contentType: req.file.mimetype,
            metadata: { cacheControl: 'public, max-age=31536000' },
          });

          let isPublic = false;
          try {
            await file.makePublic();
            isPublic = true;
          } catch (error) {
            console.warn("[Media Upload] Could not make file public:", error);
          }

          const publicGcsUrl = `https://storage.googleapis.com/${bucketId}/${objectPath}`;
          const gsPath = `gs://${bucketId}/${objectPath}`;
          storagePath = isPublic ? publicGcsUrl : gsPath;
        } catch (gcsError) {
          console.error("[Media Upload] GCS upload failed and no Cloudflare fallback available:", gcsError);
          return res.status(502).json({
            message: "تعذّر رفع الملف. خدمة التخزين السحابي غير متاحة حالياً.",
          });
        }
      }

      // Extract real dimensions for images via sharp (the columns existed but
      // were always left NULL before). Best-effort — a metadata failure must
      // not block the upload.
      let width: number | undefined;
      let height: number | undefined;

      if (req.file.mimetype.startsWith('image/')) {
        try {
          const meta = await sharp(req.file.buffer).metadata();
          width = meta.width;
          height = meta.height;
        } catch (err) {
          console.log("[Media Upload] Could not extract image dimensions:", err);
        }
      }

      // Upload is image-only (the multer fileFilter rejects everything else),
      // so the type is always "image". Real video/document support is a
      // separate planned feature, not this endpoint.
      const fileType = 'image';

      // Parse additional metadata from request body
      const {
        title,
        description,
        altText,
        caption,
        keywords,
        category,
        isFavorite,
        folderId,
        entityType,
        entityId,
      } = req.body;

      // Parse keywords - handle both JSON array string and comma-separated string
      let parsedKeywords: string[] = [];
      if (keywords) {
    try {
          // Try parsing as JSON first (e.g., ["keyword1", "keyword2"])
          if (typeof keywords === 'string' && keywords.trim().startsWith('[')) {
            parsedKeywords = JSON.parse(keywords);
          } else if (typeof keywords === 'string') {
            // Treat as comma-separated string
            parsedKeywords = keywords.split(',').map(k => k.trim()).filter(Boolean);
          } else if (Array.isArray(keywords)) {
            parsedKeywords = keywords;
          }
        } catch (err) {
          // If JSON parse fails, treat as comma-separated string
          parsedKeywords = keywords.split(',').map((k: string) => k.trim()).filter(Boolean);
        }
      }

      // Save to media_files table with storage path
      const [mediaFile] = await db
        .insert(mediaFiles)
        .values({
          fileName: `${objectId}.${fileExtension}`,
          originalName: req.file.originalname,
          folderId: folderId || null,
          url: storagePath, // Store GCS path, will be replaced with proxy URL
          type: fileType,
          mimeType: req.file.mimetype,
          size: req.file.size,
          width,
          height,
          title: title || null,
          description: description || null,
          altText: altText || null,
          caption: caption || null,
          keywords: parsedKeywords,
          isFavorite: isFavorite === 'true' || false,
          category: category || null,
          uploadedBy: userId,
          usedIn: entityId ? [entityId] : [],
          usageCount: entityId ? 1 : 0,
        })
        .returning();

      // Auto-save to mediaUsageLog if entityId provided
      if (entityType && entityId) {
        await db.insert(mediaUsageLog).values({
          mediaId: mediaFile.id,
          entityType,
          entityId,
          usedBy: userId,
        });
      }

      // Fetch complete details with folder and uploader
      // Note: We keep the gs:// path in the database for the proxy to use
      const [mediaFileWithDetails] = await db
        .select({
          id: mediaFiles.id,
          fileName: mediaFiles.fileName,
          originalName: mediaFiles.originalName,
          folderId: mediaFiles.folderId,
          url: mediaFiles.url,
          thumbnailUrl: mediaFiles.thumbnailUrl,
          type: mediaFiles.type,
          mimeType: mediaFiles.mimeType,
          size: mediaFiles.size,
          width: mediaFiles.width,
          height: mediaFiles.height,
          title: mediaFiles.title,
          description: mediaFiles.description,
          altText: mediaFiles.altText,
          caption: mediaFiles.caption,
          keywords: mediaFiles.keywords,
          isFavorite: mediaFiles.isFavorite,
          category: mediaFiles.category,
          aiAnalysisStatus: mediaFiles.aiAnalysisStatus,
          aiQualityScore: mediaFiles.aiQualityScore,
          aiHasSensitiveContent: mediaFiles.aiHasSensitiveContent,
          isAiGenerated: mediaFiles.isAiGenerated,
          licenseType: mediaFiles.licenseType,
          creditText: mediaFiles.creditText,
          copyrightHolder: mediaFiles.copyrightHolder,
          rightsVerified: mediaFiles.rightsVerified,
          rightsNote: mediaFiles.rightsNote,
          usedIn: mediaFiles.usedIn,
          usageCount: mediaFiles.usageCount,
          uploadedBy: mediaFiles.uploadedBy,
          createdAt: mediaFiles.createdAt,
          updatedAt: mediaFiles.updatedAt,
          folder: mediaFolders,
          uploader: {
            id: users.id,
            email: users.email,
            firstName: users.firstName,
            lastName: users.lastName,
            profileImageUrl: users.profileImageUrl,
          },
        })
        .from(mediaFiles)
        .leftJoin(mediaFolders, eq(mediaFiles.folderId, mediaFolders.id))
        .leftJoin(users, eq(mediaFiles.uploadedBy, users.id))
        .where(eq(mediaFiles.id, mediaFile.id));

      console.log("[Media Upload] Media file created:", mediaFileWithDetails.id);

      // Phase 2: auto-tag library images in the background. Fire-and-forget —
      // never blocks the upload response. Skips avatars/logos/reporter photos
      // and any non-public-https URL (analysis can't fetch it).
      if (shouldAutoTag({ mimeType: req.file.mimetype, url: storagePath, category, entityType })) {
        enqueueAutoTag(mediaFile.id);
      }

      // Return appropriate URL:
      // - If public: use stored public URL
      // - If not public: use proxy URL
      const responseUrl = mediaFileWithDetails.url.startsWith('https://') 
        ? mediaFileWithDetails.url 
        : `/api/media/proxy/${mediaFile.id}`;
      
      res.json({
        ...mediaFileWithDetails,
        url: responseUrl,
        proxyUrl: `/api/media/proxy/${mediaFile.id}`,
      });
    } catch (error: any) {
      console.error("Error uploading media file:", error);

      if (error.code === 'LIMIT_FILE_SIZE') {
        return res.status(400).json({ message: "الملف كبير جداً. الحد الأقصى 10MB" });
      }

      if (error.message?.includes('نوع الملف')) {
        return res.status(400).json({ message: error.message });
      }

      res.status(500).json({ message: "فشل في رفع ملف الوسائط" });
    }
  });


  // GET /api/media/proxy/:id - Proxy endpoint to serve media files from Object Storage
  app.get("/api/media/proxy/:id", async (req, res) => {
    try {
      const { id } = req.params;

      // Get media file record
      const [mediaFile] = await db
        .select()
        .from(mediaFiles)
        .where(eq(mediaFiles.id, id));

      if (!mediaFile) {
        return res.status(404).json({ message: "الملف غير موجود" });
      }

      const storagePath = mediaFile.url;
      
      // Handle different URL types
      
      // Type 1: Public URLs (https://) - redirect only to known storage hosts.
      // An unvalidated redirect to a stored (possibly user-supplied) value is
      // an open redirect, so reject anything outside our storage origins.
      if (storagePath.startsWith('https://') || storagePath.startsWith('http://')) {
        if (isAllowedMediaUrl(storagePath, req.get('host'))) {
          return res.redirect(storagePath);
        }
        console.warn('[Media Proxy] Blocked redirect to non-allowlisted host:', storagePath);
        return res.status(400).json({ message: "مسار التخزين غير صحيح" });
      }
      
      // Type 2: Public object paths (/public-objects/) - redirect to public route
      if (storagePath.startsWith('/public-objects/')) {
        return res.redirect(storagePath);
      }
      
      // Type 3: GCS paths (gs://) - stream from Object Storage
      if (storagePath.startsWith('gs://')) {
        const pathParts = storagePath.replace('gs://', '').split('/');
        // Extract bucket name from path (first part) and object path (remaining parts)
        const bucketName = pathParts[0];
        const objectPath = pathParts.slice(1).join('/');

        // Get file from Object Storage
        const { objectStorageClient, getBucketConfig } = await import('./objectStorage');

        // Validate the bucket matches the configured bucket to prevent SSRF
        const bucketConfig = getBucketConfig();
        if (bucketName !== bucketConfig.bucketName) {
          return res.status(403).json({ message: "وصول مرفوض" });
        }

        console.log('[Media Proxy] Streaming from bucket:', bucketName, 'path:', objectPath);

        const bucket = objectStorageClient.bucket(bucketName);
        const file = bucket.file(objectPath);

        // Check if file exists
        const [exists] = await file.exists();
        if (!exists) {
          return res.status(404).json({ message: "الملف غير موجود في التخزين" });
        }

        // Enforce ACL policy — mirrors the reference GET /objects/:objectPath(*) route.
        // If the object is explicitly ACL-public, serve it freely.
        // Otherwise enforce per-user access control; unauthenticated or unauthorized → 401.
        const aclPolicy = await getObjectAclPolicy(file);
        if (aclPolicy?.visibility !== "public") {
          const userId = (req as any).user?.id ? String((req as any).user.id) : undefined;
          const canAccess = await canAccessObject({
            userId,
            objectFile: file,
            requestedPermission: ObjectPermission.READ,
          });
          if (!canAccess) {
            return res.status(401).json({ message: "يجب تسجيل الدخول للوصول إلى هذا المحتوى" });
          }
        }

        // Stream the file to response
        res.setHeader('Content-Type', mediaFile.mimeType);
        res.setHeader('Cache-Control', 'public, max-age=31536000, s-maxage=86400, stale-while-revalidate=86400, immutable'); // CDN + browser cache
        
        file.createReadStream()
          .on('error', (error) => {
            console.error('[Media Proxy] Error streaming file:', error);
            if (!res.headersSent) {
              res.status(500).json({ message: "فشل في تحميل الملف" });
            }
          })
          .pipe(res);
        
        return;
      }
      
      // Invalid storage path format
      return res.status(400).json({ message: "مسار التخزين غير صحيح" });

    } catch (error) {
      console.error('[Media Proxy] Error:', error);
      if (!res.headersSent) {
        res.status(500).json({ message: "فشل في تحميل الملف" });
      }
    }
  });


  // POST /api/media/save-existing - Save existing image to media library (JSON endpoint for auto-save from editor)
  app.post("/api/media/save-existing", isAuthenticated, requirePermission("media.view"), async (req: any, res) => {
    try {
      const userId = req.user.id;
      const { url, fileName, title, description, category } = req.body;

      // Validation
      if (!url || !fileName) {
        return res.status(400).json({ message: "URL والاسم مطلوبان" });
      }
      // Only accept URLs from our own storage origins (prevents storing an
      // attacker-controlled URL that the media proxy would later redirect to).
      if (typeof url !== 'string' || !isAllowedMediaUrl(url, req.get('host'))) {
        return res.status(400).json({ message: "رابط غير صالح" });
      }

      // Reuse the existing row if this URL is already registered — stops the
      // unbounded duplicate rows that accumulated on every article edit/save.
      const [existing] = await db
        .select()
        .from(mediaFiles)
        .where(eq(mediaFiles.url, url))
        .limit(1);
      if (existing) {
        return res.json(existing);
      }

      // Infer the mime type from the extension instead of hardcoding jpeg.
      const ext = (String(fileName).split('.').pop() || '').toLowerCase();
      const extMime: Record<string, string> = {
        jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png',
        webp: 'image/webp', gif: 'image/gif', svg: 'image/svg+xml', avif: 'image/avif',
      };
      const mimeType = extMime[ext] || 'image/jpeg';

      // Create media file record
      const [mediaFile] = await db.insert(mediaFiles).values({
        fileName,
        originalName: fileName,
        url,
        type: "image",
        mimeType,
        size: 0, // Unknown for externally-referenced URLs
        title: title || fileName,
        description,
        category: category || "articles",
        uploadedBy: userId,
      }).returning();

      res.json(mediaFile);
    } catch (error) {
      console.error("Error saving media metadata:", error);
      res.status(500).json({ message: "فشل حفظ البيانات" });
    }
  });


  // PUT /api/media/:id - Update media file metadata
  app.put("/api/media/:id", isAuthenticated, requirePermission("media.view"), async (req: any, res) => {
    try {
      const mediaId = req.params.id;
      const userId = req.user.id;

      // Check if media file exists and user has permission
      const [existingMedia] = await db
        .select()
        .from(mediaFiles)
        .where(eq(mediaFiles.id, mediaId))
        .limit(1);

      if (!existingMedia) {
        return res.status(404).json({ message: "ملف الوسائط غير موجود" });
      }

      // Owner can always edit their own file; otherwise media.edit is required
      // (editors and media managers have it; admins via wildcard). The old code
      // checked the non-existent code 'media:manage' (colon), so the override
      // was dead even for admins and media managers.
      const isOwner = existingMedia.uploadedBy === userId;
      const canManageAny = await userHasPermission(userId, 'media.edit');

      if (!isOwner && !canManageAny) {
        return res.status(403).json({ message: "غير مصرح لك بتحديث هذا الملف" });
      }

      // Validate update data
      const { updateMediaFileSchema } = await import('@shared/schema');
      const parsed = updateMediaFileSchema.safeParse(req.body);

      if (!parsed.success) {
        return res.status(400).json({
          message: "بيانات غير صحيحة",
          errors: parsed.error.errors,
        });
      }

      // Update media file
      const [updatedMedia] = await db
        .update(mediaFiles)
        .set({
          ...parsed.data,
          updatedAt: new Date(),
        })
        .where(eq(mediaFiles.id, mediaId))
        .returning();

      res.json(updatedMedia);
    } catch (error) {
      console.error("Error updating media file:", error);
      res.status(500).json({ message: "فشل في تحديث ملف الوسائط" });
    }
  });


  // DELETE /api/media/:id - Delete media file
  app.delete("/api/media/:id", isAuthenticated, requirePermission("media.view"), async (req: any, res) => {
    try {
      const mediaId = req.params.id;
      const userId = req.user.id;

      // Check if media file exists
      const [existingMedia] = await db
        .select()
        .from(mediaFiles)
        .where(eq(mediaFiles.id, mediaId))
        .limit(1);

      if (!existingMedia) {
        return res.status(404).json({ message: "ملف الوسائط غير موجود" });
      }

      // Owner can delete their own file; otherwise media.delete is required
      // (media managers have it; admins via wildcard). The old code checked the
      // non-existent code 'media:manage' (colon), so the override never worked.
      const isOwner = existingMedia.uploadedBy === userId;
      const canManageAny = await userHasPermission(userId, 'media.delete');

      if (!isOwner && !canManageAny) {
        return res.status(403).json({ message: "غير مصرح لك بحذف هذا الملف" });
      }

      // Live referential check. The legacy `usedIn` array was written only at
      // upload time and never updated, so it almost never reflected reality —
      // meanwhile article_media_assets.media_file_id is ON DELETE CASCADE, so
      // deleting here would silently destroy every per-article alt/caption/SEO
      // row across all locales. Block the delete if the file is still referenced.
      const [assetRef] = await db
        .select({ articleId: articleMediaAssets.articleId })
        .from(articleMediaAssets)
        .where(eq(articleMediaAssets.mediaFileId, mediaId))
        .limit(1);
      const [usageRef] = await db
        .select({ id: mediaUsageLog.id })
        .from(mediaUsageLog)
        .where(eq(mediaUsageLog.mediaId, mediaId))
        .limit(1);
      const legacyUsed = !!(existingMedia.usedIn && existingMedia.usedIn.length > 0);

      if (assetRef || usageRef || legacyUsed) {
        const articleIds = new Set<string>();
        if (assetRef?.articleId) articleIds.add(assetRef.articleId);
        (existingMedia.usedIn || []).forEach((x) => { if (x) articleIds.add(x); });
        return res.status(400).json({
          message: "لا يمكن حذف الملف لأنه مستخدم في مقالات أو محتوى آخر",
          usedIn: Array.from(articleIds),
        });
      }

      // Remove the underlying blob from the correct backend (CF Images vs GCS/S3).
      await deleteMediaBlob(existingMedia.url);

      // Delete from database
      await db.delete(mediaFiles).where(eq(mediaFiles.id, mediaId));

      res.json({ message: "تم حذف ملف الوسائط بنجاح" });
    } catch (error) {
      console.error("Error deleting media file:", error);
      res.status(500).json({ message: "فشل في حذف ملف الوسائط" });
    }
  });


