  // Simplified avatar upload endpoint - single step upload
  const avatarUpload = multer({
    storage: multer.memoryStorage(),
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB max
    },
    fileFilter: (req, file, cb) => {
      const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
      if (allowedTypes.includes(file.mimetype)) {
        cb(null, true);
      } else {
        cb(new Error('نوع الملف غير مسموح. الأنواع المسموحة: JPG, PNG, WEBP'));
      }
    },
  });


  app.post("/api/profile/upload-avatar", isAuthenticated, strictLimiter, avatarUpload.single('avatar'), async (req: any, res) => {
    try {
      const userId = req.user.id;
      
      if (!req.file) {
        return res.status(400).json({ message: "لم يتم اختيار ملف" });
      }

      console.log("[Avatar Upload] File received:", {
        originalName: req.file.originalname,
        mimetype: req.file.mimetype,
        size: req.file.size
      });

      // Extract bucket ID from PRIVATE_OBJECT_DIR
      const privateObjectDir = process.env.PRIVATE_OBJECT_DIR || '';
      
      // PRIVATE_OBJECT_DIR can be in format: "bucket-name/.private" or "/objects/bucket-name/.private"
      const parts = privateObjectDir.split('/').filter(Boolean);
      let bucketId: string;
      
      if (parts.length >= 2 && parts[0] === 'objects') {
        // Format: /objects/bucket-name/.private
        bucketId = parts[1];
      } else if (parts.length >= 1) {
        // Format: bucket-name/.private
        bucketId = parts[0];
      } else {
        throw new Error('Invalid PRIVATE_OBJECT_DIR format');
      }

      if (!bucketId) {
        throw new Error('Bucket ID not found in PRIVATE_OBJECT_DIR');
      }

      // Generate unique filename (security audit H2: validate extension)
      const rawExt = req.file.originalname.split('.').pop()?.toLowerCase() || 'jpg';
      const fileExtension = /^[a-z0-9]{1,5}$/.test(rawExt) ? rawExt : 'bin';
      const objectId = randomUUID();

      // Build object path (simple, no complex directory structure)
      const objectPath = `uploads/avatars/${objectId}.${fileExtension}`;

      console.log("[Avatar Upload] Uploading to bucket:", bucketId, "path:", objectPath);

      // Upload file to GCS (without public access as bucket has public access prevention)
      const { objectStorageClient, getBucketConfig } = await import('./objectStorage');
      const bucket = objectStorageClient.bucket(bucketId);
      const file = bucket.file(objectPath);

      await file.save(req.file.buffer, {
        contentType: req.file.mimetype,
      });

      // Set ACL policy: avatars are profile pictures and must be publicly readable
      await setObjectAclPolicy(file, {
        owner: String(userId),
        visibility: "public",
      });

      console.log("[Avatar Upload] File uploaded successfully");

      // Store the storage path and build proxy URL
      const storagePath = `gs://${bucketId}/${objectPath}`;
      const publicUrl = `/api/media/proxy-avatar/${encodeURIComponent(storagePath)}`;

      console.log("[Avatar Upload] Using proxy URL:", publicUrl);

      // Update user profile with the public URL
      const user = await storage.updateUser(userId, { 
        profileImageUrl: publicUrl 
      });

      console.log("[Avatar Upload] User updated with new avatar:", user.profileImageUrl);

      res.json({ 
        success: true,
        profileImageUrl: publicUrl,
        user
      });
    } catch (error: any) {
      console.error("Error uploading avatar:", error);
      
      // Handle multer errors
      if (error.code === 'LIMIT_FILE_SIZE') {
        return res.status(400).json({ message: "الملف كبير جداً. الحد الأقصى 5MB" });
      }
      
      if (error.message?.includes('نوع الملف')) {
        return res.status(400).json({ message: error.message });
      }

      res.status(500).json({ message: "فشل في رفع الصورة" });
    }
  });


  // GET /api/media/proxy-avatar/:storagePath - Proxy endpoint for avatar images
  app.get("/api/media/proxy-avatar/:storagePath", async (req, res) => {
    try {
      const storagePath = decodeURIComponent(req.params.storagePath);

      if (!storagePath.startsWith('gs://')) {
        return res.status(400).json({ message: "مسار التخزين غير صحيح" });
      }

      const pathParts = storagePath.replace('gs://', '').split('/');
      const bucketName = pathParts[0];
      const objectPath = pathParts.slice(1).join('/');

      if (!objectPath) {
        return res.status(400).json({ message: "مسار الملف غير صحيح" });
      }

      const { objectStorageClient, getBucketConfig } = await import('./objectStorage');

      // Validate the bucket matches the configured bucket to prevent SSRF
      const bucketConfig = getBucketConfig();
      if (bucketName !== bucketConfig.bucketName) {
        return res.status(403).json({ message: "وصول مرفوض" });
      }

      const bucket = objectStorageClient.bucket(bucketName);
      const file = bucket.file(objectPath);

      const [exists] = await file.exists();
      if (!exists) {
        console.error('[Avatar Proxy] File not found:', { bucketName, objectPath });
        return res.status(404).json({ message: "الصورة غير موجودة في التخزين" });
      }

      // Enforce ACL policy — mirrors the reference GET /objects/:objectPath(*) route.
      // Avatars are set to ACL-public on upload; unauthenticated access to non-public objects → 401.
      const aclPolicy = await getObjectAclPolicy(file);
      if (aclPolicy?.visibility !== "public") {
        const userId = (req as any).user?.id ? String((req as any).user.id) : undefined;
        const canAccess = await canAccessObject({
          userId,
          objectFile: file,
          requestedPermission: ObjectPermission.READ,
        });
        if (!canAccess) {
          return res.status(401).json({ message: "يجب تسجيل الدخول للوصول إلى هذا المحتوى" });
        }
      }

      const ext = objectPath.split('.').pop()?.toLowerCase() || 'jpg';
      // SVG removed (security audit H3, 2026-05-11). SVGs can embed
      // <script> and execute in any context the proxy serves them in;
      // refusing here is defense-in-depth — uploads already block them
      // at the multer fileFilter layer, but legacy objects might exist.
      if (ext === 'svg' || ext === 'svgz') {
        return res.status(415).json({ message: "نوع الملف غير مدعوم" });
      }
      const mimeTypes: Record<string, string> = {
        'png': 'image/png',
        'jpg': 'image/jpeg',
        'jpeg': 'image/jpeg',
        'gif': 'image/gif',
        'webp': 'image/webp',
      };
      const contentType = mimeTypes[ext] || 'image/jpeg';

      res.setHeader('Content-Type', contentType);
      res.setHeader('Cache-Control', 'public, max-age=31536000, s-maxage=86400, stale-while-revalidate=86400, immutable');
      
      file.createReadStream()
        .on('error', (error) => {
          console.error('[Avatar Proxy] Error streaming file:', error);
          if (!res.headersSent) {
            res.status(500).json({ message: "فشل في تحميل الصورة" });
          }
        })
        .pipe(res);

    } catch (error) {
      console.error('[Avatar Proxy] Error:', error);
      if (!res.headersSent) {
        res.status(500).json({ message: "فشل في تحميل الصورة" });
      }
    }
  });


  // GET /api/public-media/* - Proxy endpoint for public media files (email/whatsapp attachments)

  // GET /api/storage/proxy/:gsPath - Generic proxy endpoint for gs:// URLs (thumbnails, etc.)
  app.get("/api/storage/proxy/:gsPath", async (req, res) => {
    try {
      const gsPath = decodeURIComponent(req.params.gsPath);

      if (!gsPath.startsWith('gs://')) {
        return res.status(400).json({ message: "مسار التخزين غير صحيح" });
      }

      // Parse gs:// URL: gs://bucket-name/path/to/file
      const pathWithoutPrefix = gsPath.replace('gs://', '');
      const slashIndex = pathWithoutPrefix.indexOf('/');
      
      if (slashIndex === -1) {
        return res.status(400).json({ message: "مسار الملف غير صحيح" });
      }

      const bucketName = pathWithoutPrefix.substring(0, slashIndex);
      const objectPath = pathWithoutPrefix.substring(slashIndex + 1);

      // Get file from Object Storage
      const { objectStorageClient, getBucketConfig } = await import('./objectStorage');

      // Validate the bucket matches the configured bucket to prevent SSRF
      const bucketConfig = getBucketConfig();
      if (bucketName !== bucketConfig.bucketName) {
        return res.status(403).json({ message: "وصول مرفوض" });
      }

      const bucket = objectStorageClient.bucket(bucketName);
      const file = bucket.file(objectPath);

      // Check if file exists
      const [exists] = await file.exists();
      if (!exists) {
        console.error(`[Storage Proxy] File not found: ${gsPath}`);
        return res.status(404).json({ message: "الملف غير موجود" });
      }

      // Enforce ACL policy — mirrors the reference GET /objects/:objectPath(*) route.
      // If the object is explicitly ACL-public, serve it freely.
      // Otherwise enforce per-user access control; unauthenticated or unauthorized → 401.
      const aclPolicy = await getObjectAclPolicy(file);
      if (aclPolicy?.visibility !== "public") {
        const userId = (req as any).user?.id ? String((req as any).user.id) : undefined;
        const canAccess = await canAccessObject({
          userId,
          objectFile: file,
          requestedPermission: ObjectPermission.READ,
        });
        if (!canAccess) {
          return res.status(401).json({ message: "يجب تسجيل الدخول للوصول إلى هذا المحتوى" });
        }
      }

      // Get file metadata to determine content type
      const [metadata] = await file.getMetadata();
      const contentType = metadata.contentType || 'application/octet-stream';

      // Set response headers
      res.setHeader('Content-Type', contentType);
      res.setHeader('Cache-Control', 'public, max-age=31536000, s-maxage=86400, stale-while-revalidate=86400, immutable'); // CDN + browser cache
      
      // Stream the file to response
      file.createReadStream()
        .on('error', (error) => {
          console.error('[Storage Proxy] Error streaming file:', error);
          if (!res.headersSent) {
            res.status(500).json({ message: "فشل في تحميل الملف" });
          }
        })
        .pipe(res);

    } catch (error) {
      console.error('[Storage Proxy] Error:', error);
      if (!res.headersSent) {
        res.status(500).json({ message: "فشل في تحميل الملف" });
      }
    }
  });

  app.get("/api/public-media/*", async (req: any, res) => {
    try {
      // Extract the full path after /api/public-media/
      const fullPath = req.params[0] as string;

      if (!fullPath) {
        console.error(`[Public Media Proxy] Empty file path requested`);
        return res.status(400).json({ message: "مسار الملف مطلوب" });
      }

      // The underlying objectStorageClient uses Replit's sidecar workload
      // identity federation (127.0.0.1:1106). On Railway that endpoint
      // doesn't exist and every call fails with ECONNREFUSED → unhandled
      // stack trace in the logs. Short-circuit to 404 (cached for a day)
      // when not running on Replit. Migrated legacy /public-media/* URLs
      // already point at CF Images; the surviving callers are crawlers
      // chasing old Arabic article references and should give up.
      if (!process.env.REPLIT_DOMAINS && !process.env.REPL_ID) {
        res.setHeader('Cache-Control', 'public, max-age=86400');
        return res.status(404).json({ message: "الملف غير متاح" });
      }

      // Get file from Object Storage
      const { objectStorageClient, getBucketConfig } = await import('./objectStorage');

      // Use getBucketConfig for reliable bucket resolution
      const { bucketName, publicPrefix } = getBucketConfig();

      // Normalize the path to prevent directory traversal and enforce it is
      // strictly under the configured public prefix.
      const normalizedPath = fullPath.replace(/\.\./g, '').replace(/\/+/g, '/').replace(/^\//, '');
      const isUnderPublicPrefix = normalizedPath.startsWith(publicPrefix + '/') ||
        normalizedPath === publicPrefix;
      if (!isUnderPublicPrefix) {
        console.error(`[Public Media Proxy] Rejected non-public path: "${fullPath}"`);
        return res.status(403).json({ message: "وصول مرفوض" });
      }

      const bucket = objectStorageClient.bucket(bucketName);
      const file = bucket.file(normalizedPath);

      console.log(`[Public Media Proxy] Looking for file: bucket="${bucketName}", path="${normalizedPath}"`);
      
      // Check if file exists
      const [exists] = await file.exists();
      if (!exists) {
        console.error(`[Public Media Proxy] File not found: bucket=${bucketName}, path=${normalizedPath}`);
        return res.status(404).json({ message: "الملف غير موجود في التخزين" });
      }
      console.log(`[Public Media Proxy] File found! Streaming...`);

      // Get file metadata to determine content type
      const [metadata] = await file.getMetadata();
      const contentType = metadata.contentType || 'application/octet-stream';

      // Stream the file to response
      res.setHeader('Content-Type', contentType);
      res.setHeader('Cache-Control', 'public, max-age=31536000, s-maxage=86400, stale-while-revalidate=86400, immutable'); // CDN + browser cache
      res.setHeader('Access-Control-Allow-Origin', '*'); // Allow CORS for public files
      
      file.createReadStream()
        .on('error', (error) => {
          console.error('[Public Media Proxy] Error streaming file:', error);
          if (!res.headersSent) {
            res.status(500).json({ message: "فشل في تحميل الملف" });
          }
        })
        .pipe(res);

    } catch (error) {
      console.error('[Public Media Proxy] Error:', error);
      if (!res.headersSent) {
        res.status(500).json({ message: "فشل في تحميل الملف" });
      }
    }
  });


