  // Get all categories
  app.get("/api/categories", (req, res, next) => {
    const withStats = req.query.withStats === 'true';
    const ttl = withStats ? CACHE_DURATIONS.SHORT : CACHE_DURATIONS.LONG;
    return cacheControl({ maxAge: ttl, staleWhileRevalidate: ttl })(req, res, next);
  }, async (req, res) => {
    try {
      const withStats = req.query.withStats === 'true';
      const includeIfox = req.query.includeIfox === 'true';

      const cacheKey = `categories:list:${withStats}:${includeIfox}`;
      const ttl = withStats ? CACHE_TTL.SHORT : CACHE_TTL.LONG;
      const result = await withSWR(cacheKey, ttl, ttl * 2, async () => {
        if (withStats) {
          let cats = await storage.getCategoriesWithStats();
          if (!includeIfox) {
            cats = cats.filter(c => !c.isIfoxCategory);
          }
          return cats;
        } else {
          return await storage.getAllCategories({ excludeIfox: !includeIfox });
        }
      });
      res.json(result);
    } catch (error) {
      console.error("Error fetching categories:", error);
      res.status(500).json({ message: "Failed to fetch categories" });
    }
  });


  // Get all English categories
  app.get("/api/en/categories", cacheControl({ maxAge: CACHE_DURATIONS.LONG, staleWhileRevalidate: CACHE_DURATIONS.LONG }), async (req, res) => {
    try {
      const withStats = req.query.withStats === 'true';
      const enCacheKey = `en:categories:${withStats}`;
      const enCached = memoryCache.get(enCacheKey);
      if (enCached) return res.json(enCached);
      
      if (withStats) {
        // Get categories with statistics
        const allCategories = await db
          .select()
          .from(enCategories)
          .where(eq(enCategories.status, 'active'))
          .orderBy(asc(enCategories.displayOrder));

        // Get stats for each category
        const categoriesWithStats = await Promise.all(
          allCategories.map(async (category) => {
            // Count articles
            const [{ articleCount }] = await db
              .select({ articleCount: sql<number>`count(*)::int` })
              .from(enArticles)
              .where(
                and(
                  eq(enArticles.categoryId, category.id),
                  eq(enArticles.status, "published")
                )
              );

            // Sum views
            const [{ totalViews }] = await db
              .select({ totalViews: sql<number>`coalesce(sum(${enArticles.views}), 0)::int` })
              .from(enArticles)
              .where(
                and(
                  eq(enArticles.categoryId, category.id),
                  eq(enArticles.status, "published")
                )
              );

            // Count likes (from reactions table for English articles)
            const [{ totalLikes }] = await db
              .select({ totalLikes: sql<number>`count(*)::int` })
              .from(reactions)
              .innerJoin(enArticles, eq(enArticles.id, reactions.articleId))
              .where(
                and(
                  eq(enArticles.categoryId, category.id),
                  eq(enArticles.status, "published"),
                  eq(reactions.type, "like")
                )
              );

            // Count bookmarks
            const [{ totalBookmarks }] = await db
              .select({ totalBookmarks: sql<number>`count(*)::int` })
              .from(bookmarks)
              .innerJoin(enArticles, eq(enArticles.id, bookmarks.articleId))
              .where(
                and(
                  eq(enArticles.categoryId, category.id),
                  eq(enArticles.status, "published")
                )
              );

            return {
              ...category,
              articleCount: articleCount || 0,
              totalViews: totalViews || 0,
              totalLikes: totalLikes || 0,
              totalBookmarks: totalBookmarks || 0,
            };
          })
        );

        memoryCache.set(enCacheKey, categoriesWithStats, CACHE_TTL.LONG);
        res.json(categoriesWithStats);
      } else {
        const categories = await db
          .select()
          .from(enCategories)
          .where(eq(enCategories.status, 'active'))
          .orderBy(asc(enCategories.displayOrder));

        memoryCache.set(enCacheKey, categories, CACHE_TTL.LONG);
        res.json(categories);
      }
    } catch (error) {
      console.error("Error fetching English categories:", error);
      res.status(500).json({ message: "Failed to fetch English categories" });
    }
  });


