  // Update user (status, role assignment)
  app.patch("/api/admin/users/:id", requireAuth, requirePermission("users.update"), async (req: any, res) => {
    try {
      const adminUserId = req.user?.id;
      if (!adminUserId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const targetUserId = req.params.id;

      // Prevent self-modification to avoid privilege escalation/demotion
      if (targetUserId === adminUserId) {
        return res.status(403).json({ message: "Cannot modify your own account" });
      }

      const parsed = adminUpdateUserSchema.safeParse(req.body);

      if (!parsed.success) {
        return res.status(400).json({
          message: "Invalid data",
          errors: parsed.error.flatten().fieldErrors,
        });
      }

      // Get old user data for logging
      const [oldUser] = await db
        .select()
        .from(users)
        .where(eq(users.id, targetUserId))
        .limit(1);

      if (!oldUser) {
        return res.status(404).json({ message: "User not found" });
      }

      // Build update object with all provided fields
      const updateData: any = {};
      
      // Handle email update - only system_admin can change emails
      if (parsed.data.email !== undefined && parsed.data.email !== oldUser.email) {
        // Check if current user is system_admin
        const adminRoles = await db
          .select({ roleName: roles.name })
          .from(userRoles)
          .innerJoin(roles, eq(userRoles.roleId, roles.id))
          .where(eq(userRoles.userId, adminUserId));
        
        const isSystemAdmin = adminRoles.some(r => r.roleName === "system_admin");
        if (!isSystemAdmin) {
          return res.status(403).json({ message: "مسؤول النظام فقط يمكنه تعديل البريد الإلكتروني" });
        }
        
        const normalizedEmail = parsed.data.email.toLowerCase().trim();
        const [existingUser] = await db
          .select({ id: users.id })
          .from(users)
          .where(and(
            eq(users.email, normalizedEmail),
            ne(users.id, targetUserId)
          ))
          .limit(1);
        
        if (existingUser) {
          return res.status(400).json({ message: "البريد الإلكتروني مستخدم بالفعل من قبل مستخدم آخر" });
        }
        updateData.email = normalizedEmail;
      }
      
      if (parsed.data.firstName !== undefined) updateData.firstName = parsed.data.firstName;
      if (parsed.data.lastName !== undefined) updateData.lastName = parsed.data.lastName;
      if (parsed.data.firstNameEn !== undefined) updateData.firstNameEn = parsed.data.firstNameEn || null;
      if (parsed.data.lastNameEn !== undefined) updateData.lastNameEn = parsed.data.lastNameEn || null;
      if (parsed.data.phoneNumber !== undefined) updateData.phoneNumber = parsed.data.phoneNumber || null;
      if (parsed.data.profileImageUrl !== undefined) updateData.profileImageUrl = parsed.data.profileImageUrl || null;
      if (parsed.data.status !== undefined) updateData.status = parsed.data.status;
      if (parsed.data.emailVerified !== undefined) updateData.emailVerified = parsed.data.emailVerified;
      if (parsed.data.phoneVerified !== undefined) updateData.phoneVerified = parsed.data.phoneVerified;
      if (parsed.data.verificationBadge !== undefined) updateData.verificationBadge = parsed.data.verificationBadge;
      
      // Press Card fields (Apple Wallet Digital Press Card)
      if (parsed.data.hasPressCard !== undefined) {
        updateData.hasPressCard = parsed.data.hasPressCard;
        
        // If press card is disabled, clear all press card data
        if (!parsed.data.hasPressCard) {
          updateData.jobTitle = null;
          updateData.department = null;
          updateData.pressIdNumber = null;
          updateData.cardValidUntil = null;
        } else {
          // Only update press card fields if press card is enabled
          if (parsed.data.jobTitle !== undefined) updateData.jobTitle = parsed.data.jobTitle ?? null;
          if (parsed.data.department !== undefined) updateData.department = parsed.data.department ?? null;
          if (parsed.data.pressIdNumber !== undefined) updateData.pressIdNumber = parsed.data.pressIdNumber ?? null;
          if (parsed.data.cardValidUntil !== undefined) {
            if (parsed.data.cardValidUntil) {
              const parsedDate = new Date(parsed.data.cardValidUntil);
              if (Number.isNaN(parsedDate.getTime())) {
                return res.status(400).json({ 
                  message: "Invalid cardValidUntil date format. Expected ISO 8601 date string." 
                });
              }
              updateData.cardValidUntil = parsedDate;
            } else {
              updateData.cardValidUntil = null;
            }
          }
        }
      } else if (parsed.data.hasPressCard === undefined && oldUser.hasPressCard) {
        // Only allow updating individual fields if press card is currently enabled
        if (parsed.data.jobTitle !== undefined) updateData.jobTitle = parsed.data.jobTitle ?? null;
        if (parsed.data.department !== undefined) updateData.department = parsed.data.department ?? null;
        if (parsed.data.pressIdNumber !== undefined) updateData.pressIdNumber = parsed.data.pressIdNumber ?? null;
        if (parsed.data.cardValidUntil !== undefined) {
          if (parsed.data.cardValidUntil) {
            const parsedDate = new Date(parsed.data.cardValidUntil);
            if (Number.isNaN(parsedDate.getTime())) {
              return res.status(400).json({ 
                message: "Invalid cardValidUntil date format. Expected ISO 8601 date string." 
              });
            }
            updateData.cardValidUntil = parsedDate;
          } else {
            updateData.cardValidUntil = null;
          }
        }
      }

      // Update user data if there are any fields to update
      if (Object.keys(updateData).length > 0) {
        await db
          .update(users)
          .set(updateData)
          .where(eq(users.id, targetUserId));

        // Sync name changes to staff table if user has a staff record
        if (updateData.firstName !== undefined || updateData.lastName !== undefined) {
          const newFullName = `${updateData.firstName ?? oldUser.firstName ?? ''} ${updateData.lastName ?? oldUser.lastName ?? ''}`.trim();
          if (newFullName) {
            await db
              .update(staff)
              .set({ nameAr: newFullName, name: newFullName })
              .where(eq(staff.userId, targetUserId));
            console.log(`[ADMIN USERS] Synced name to staff table for user ${targetUserId}: "${newFullName}"`);
          }
        }
      }

      // Update role if provided
      if (parsed.data.roleId !== undefined) {
        // Verify role exists
        const [role] = await db
          .select()
          .from(roles)
          .where(eq(roles.id, parsed.data.roleId))
          .limit(1);

        if (!role) {
          return res.status(404).json({ message: "Role not found" });
        }

        // Remove existing role assignment
        await db
          .delete(userRoles)
          .where(eq(userRoles.userId, targetUserId));

        // Assign new role
        await db.insert(userRoles).values({
          userId: targetUserId,
          roleId: parsed.data.roleId,
          assignedBy: adminUserId,
        });
      }

      invalidateUserPermissionCache(targetUserId);
      invalidateUserSessionCache(targetUserId);

      // Get updated user data
      const [updatedUser] = await db
        .select({
          id: users.id,
          email: users.email,
          firstName: users.firstName,
          lastName: users.lastName,
          profileImageUrl: users.profileImageUrl,
          status: users.status,
          isProfileComplete: users.isProfileComplete,
          createdAt: users.createdAt,
          roleName: roles.name,
          roleNameAr: roles.nameAr,
          roleId: roles.id,
        })
        .from(users)
        .leftJoin(userRoles, eq(users.id, userRoles.userId))
        .leftJoin(roles, eq(userRoles.roleId, roles.id))
        .where(eq(users.id, targetUserId))
        .limit(1);

      // Log activity
      await logActivity({
        userId: adminUserId,
        action: "updated",
        entityType: "user",
        entityId: targetUserId,
        oldValue: oldUser,
        newValue: updatedUser,
        metadata: {
          ip: req.ip,
          userAgent: req.get("user-agent"),
        },
      });

      res.json(updatedUser);
    } catch (error: any) {
      console.error("Error updating user:", error);
      // Drizzle يلفّ أخطاء PG؛ extractPgError يفك code/constraint.
      const pg = extractPgError(error);
      if (pg.code === '23505') {
        if (pg.constraint === 'users_press_id_number_idx') return res.status(400).json({ message: "رقم البطاقة الصحفية موجود مسبقاً. يرجى استخدام رقم آخر." });
        if (pg.constraint === 'users_email_unique' || pg.constraint === 'users_email_lower_unique') return res.status(409).json({ message: "هذا البريد الإلكتروني مستخدم بالفعل" });
      }
      res.status(500).json({ message: "Failed to update user" });
    }
  });


  // Delete/Ban user
  app.delete("/api/admin/users/:id", requireAuth, requirePermission("users.delete"), async (req: any, res) => {
    try {
      const adminUserId = req.user?.id;
      if (!adminUserId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const targetUserId = req.params.id;

      // Prevent self-deletion
      if (targetUserId === adminUserId) {
        return res.status(403).json({ message: "Cannot delete your own account" });
      }

      const [user] = await db
        .select()
        .from(users)
        .where(eq(users.id, targetUserId))
        .limit(1);

      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      // Soft delete by setting status to banned
      await db
        .update(users)
        .set({ status: "banned" })
        .where(eq(users.id, targetUserId));

      // Log activity
      await logActivity({
        userId: adminUserId,
        action: "deleted",
        entityType: "user",
        entityId: targetUserId,
        oldValue: user,
        metadata: {
          ip: req.ip,
          userAgent: req.get("user-agent"),
        },
      });

      res.json({ message: "User deleted successfully" });
    } catch (error) {
      console.error("Error deleting user:", error);
      res.status(500).json({ message: "Failed to delete user" });
    }
  });


