  // ============================================================
  // LITE FEED - Optimized endpoint for swipe cards
  // ============================================================
  
  // maxAge:0 → the browser / iOS WKWebView always revalidates against the edge
  // instead of serving its own HTTP cache. Without this (max-age=120) the iOS
  // Lite app's WKWebView would keep returning a cached feed for ~2-4 min, so
  // pull-to-refresh showed no newly-published hero/carousel articles until the
  // app was killed and relaunched. The edge (s-maxage) still absorbs load and
  // is purged on publish via purgeHomepage(), so freshness is immediate.
  // Mirrors the /api/homepage-lite pattern, which never had this bug.
  app.get("/api/lite-feed", cacheControl({ maxAge: 0, sMaxAge: CACHE_DURATIONS.SHORT, staleWhileRevalidate: CACHE_DURATIONS.SHORT }), async (req, res) => {
    try {
      const cacheKey = 'lite-feed';
      const cached = memoryCache.get(cacheKey);
      if (cached) {
        return res.json(cached);
      }

      const result = await db
        .select({
          id: articles.id,
          slug: articles.slug,
          title: articles.title,
        subtitle: articles.subtitle,
          excerpt: articles.excerpt,
          imageUrl: articles.imageUrl,
          imageFocalPoint: articles.imageFocalPoint,
          liteOptimizedImageUrl: articles.liteOptimizedImageUrl,
          thumbnailUrl: articles.thumbnailUrl,
          categoryId: articles.categoryId,
          categoryName: categories.nameAr,
          publishedAt: articles.publishedAt,
          views: articles.views,
          newsType: articles.newsType,
          articleType: articles.articleType,
        isAiGeneratedThumbnail: articles.isAiGeneratedThumbnail,
        isAiGeneratedImage: articles.isAiGeneratedImage,
        infographicBannerUrl: articles.infographicBannerUrl,
        categoryColor: categories.color,
          isVideoTemplate: articles.isVideoTemplate,
          videoUrl: articles.videoUrl,
          videoThumbnailUrl: articles.videoThumbnailUrl,
        })
        .from(articles)
        .leftJoin(categories, eq(articles.categoryId, categories.id))
        .where(and(
          eq(articles.status, 'published'),
          eq(articles.hideFromHomepage, false)
        ))
        .orderBy(desc(articles.publishedAt))
        .limit(30);
      
      const formatted = result.map(row => ({
        id: row.id,
        slug: row.slug,
        title: row.title,
        subtitle: row.subtitle,
        excerpt: row.excerpt,
        imageUrl: row.liteOptimizedImageUrl || row.imageUrl,
        liteOptimizedImageUrl: row.liteOptimizedImageUrl,
        thumbnailUrl: row.thumbnailUrl,
        imageFocalPoint: row.imageFocalPoint,
        categoryId: row.categoryId,
        publishedAt: row.publishedAt,
        views: row.views,
        newsType: row.newsType,
        articleType: row.articleType,
        isAiGeneratedThumbnail: row.isAiGeneratedThumbnail,
        isAiGeneratedImage: row.isAiGeneratedImage,
        infographicBannerUrl: row.infographicBannerUrl,
        category: row.categoryId ? { id: row.categoryId, nameAr: row.categoryName, color: row.categoryColor } : null,
        isVideoTemplate: row.isVideoTemplate,
        videoUrl: row.videoUrl,
        videoThumbnailUrl: row.videoThumbnailUrl,
      }));
      
      memoryCache.set(cacheKey, formatted, CACHE_TTL.SHORT);
      res.json(formatted);
    } catch (error) {
      console.error('[Lite Feed] Error:', error);
      res.status(500).json({ error: 'Failed to fetch lite feed' });
    }
  });

