  app.get("/api/news/paginated", cacheControl({ maxAge: 0, sMaxAge: 15, staleWhileRevalidate: 15 }), async (req, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit as string) || 8, 50);
      const offset = parseInt(req.query.offset as string) || 0;
      
      const total = await withSWR('news-paginated-total', CACHE_TTL.SHORT, CACHE_TTL.SHORT * 2, async () => {
        const [countResult] = await db
          .select({ count: sql<number>`count(*)::int` })
          .from(articles)
          .where(and(
            eq(articles.status, "published"),
            eq(articles.hideFromHomepage, false),
            or(isNull(articles.articleType), ne(articles.articleType, "opinion")),
            or(isNull(articles.source), ne(articles.source, "ai"))
          ));
        return countResult?.count || 0;
      });
      
      const paginatedArticles = await db
        .select({
          id: articles.id,
          title: articles.title,
          subtitle: articles.subtitle,
          slug: articles.slug,
          englishSlug: articles.englishSlug,
          excerpt: articles.excerpt,
          imageUrl: articles.imageUrl,
          thumbnailUrl: articles.thumbnailUrl,
          imageFocalPoint: articles.imageFocalPoint,
          publishedAt: articles.publishedAt,
          categoryId: articles.categoryId,
          views: articles.views,
          newsType: articles.newsType,
          articleType: articles.articleType,
          isAiGeneratedThumbnail: articles.isAiGeneratedThumbnail,
          isAiGeneratedImage: articles.isAiGeneratedImage,
          infographicBannerUrl: articles.infographicBannerUrl,
          isVideoTemplate: articles.isVideoTemplate,
          aiGenerated: articles.aiGenerated,
          categoryName: categories.nameAr,
          categoryColor: categories.color,
          categorySlug: categories.slug,
        })
        .from(articles)
        .leftJoin(categories, eq(articles.categoryId, categories.id))
        .where(and(
          eq(articles.status, "published"),
          eq(articles.hideFromHomepage, false),
          or(isNull(articles.articleType), ne(articles.articleType, "opinion")),
          or(isNull(articles.source), ne(articles.source, "ai"))
        ))
        .orderBy(desc(articles.publishedAt))
        .limit(limit)
        .offset(offset);
      
      let pollArticleIds = new Set<string>();
      let commentsMap = new Map<string, number>();
      if (paginatedArticles.length > 0) {
        const articleIds = paginatedArticles.map(a => a.id);
        const [activePolls, commentsCountResult] = await Promise.all([
          db.select({ articleId: articlePolls.articleId })
            .from(articlePolls)
            .where(and(
              inArray(articlePolls.articleId, articleIds),
              eq(articlePolls.isActive, true)
            )),
          db.select({
            articleId: comments.articleId,
            count: sql<number>`COUNT(*)::int`
          })
          .from(comments)
          .where(inArray(comments.articleId, articleIds))
          .groupBy(comments.articleId)
        ]);
        
        pollArticleIds = new Set(activePolls.map(p => p.articleId));
        commentsMap = new Map(commentsCountResult.map(r => [r.articleId, r.count]));
      }

      const formattedArticles = paginatedArticles.map(row => ({
        id: row.id,
        title: row.title,
        subtitle: row.subtitle,
        slug: row.slug,
        englishSlug: row.englishSlug,
        excerpt: row.excerpt,
        imageUrl: row.imageUrl,
        thumbnailUrl: row.thumbnailUrl,
        imageFocalPoint: row.imageFocalPoint,
        publishedAt: row.publishedAt,
        categoryId: row.categoryId,
        views: row.views,
        newsType: row.newsType,
        articleType: row.articleType,
        isAiGeneratedThumbnail: row.isAiGeneratedThumbnail,
        isAiGeneratedImage: row.isAiGeneratedImage,
        infographicBannerUrl: row.infographicBannerUrl,
        isVideoTemplate: row.isVideoTemplate,
        aiGenerated: row.aiGenerated,
        commentsCount: commentsMap.get(row.id) || 0,
        hasPoll: pollArticleIds.has(row.id),
        category: row.categoryId ? {
          id: row.categoryId,
          nameAr: row.categoryName,
          color: row.categoryColor,
          slug: row.categorySlug,
        } : null,
      }));

      res.json({
        articles: formattedArticles,
        hasMore: offset + paginatedArticles.length < total,
        total,
      });
    } catch (error) {
      console.error("Error fetching paginated news:", error);
      res.status(500).json({ message: "Failed to fetch news" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights
  app.get("/api/news/analytics", async (req, res) => {
    try {
      const analyticsData = await withSWR('news-analytics-ar', CACHE_TTL.MEDIUM, CACHE_TTL.MEDIUM * 2, async () => {
        const now = new Date();
        const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
        const monthAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);
        const prevMonthStart = new Date(monthAgo.getTime() - 30 * 24 * 60 * 60 * 1000);

        const periodResult = await db.execute(sql`
          SELECT
            COUNT(*) FILTER (WHERE published_at >= ${today})::int AS today_count,
            COUNT(*) FILTER (WHERE published_at >= ${weekAgo})::int AS week_count,
            COUNT(*) FILTER (WHERE published_at >= ${monthAgo})::int AS month_count,
            COUNT(*) FILTER (WHERE published_at >= ${prevMonthStart} AND published_at < ${monthAgo})::int AS prev_month_count
          FROM articles
          WHERE status = 'published'
            AND hide_from_homepage = false
            AND (article_type IS NULL OR article_type != 'opinion')
        `);
        const periodRows = (periodResult as any).rows || periodResult;
        const periodCounts = Array.isArray(periodRows) ? periodRows[0] : periodRows;

        const todayC = (periodCounts as any)?.today_count || 0;
        const weekC = (periodCounts as any)?.week_count || 0;
        const monthC = (periodCounts as any)?.month_count || 0;
        const prevMonthC = (periodCounts as any)?.prev_month_count || 0;

        const growthPercentage = prevMonthC > 0
          ? ((monthC - prevMonthC) / prevMonthC) * 100
          : 0;

        const topCategory = await db.select({
          categoryId: articles.categoryId,
          count: sql<number>`count(*)::int`,
          name: categories.nameAr,
          icon: categories.icon,
          color: categories.color,
        })
          .from(articles)
          .leftJoin(categories, eq(articles.categoryId, categories.id))
          .where(and(
            gte(articles.publishedAt, monthAgo),
            eq(articles.status, "published"),
            eq(articles.hideFromHomepage, false),
            or(isNull(articles.articleType), ne(articles.articleType, 'opinion'))
          ))
          .groupBy(articles.categoryId, categories.nameAr, categories.icon, categories.color)
          .orderBy(sql`count(*) DESC`)
          .limit(1);

        let topAuthor = await db.select({
          userId: articles.reporterId,
          count: sql<number>`count(*)::int`,
          firstName: users.firstName,
          lastName: users.lastName,
          profileImageUrl: users.profileImageUrl,
        })
          .from(articles)
          .innerJoin(users, eq(articles.reporterId, users.id))
          .where(and(
            gte(articles.publishedAt, monthAgo),
            eq(articles.status, "published"),
            eq(articles.hideFromHomepage, false),
            or(isNull(articles.articleType), ne(articles.articleType, 'opinion')),
            isNotNull(articles.reporterId)
          ))
          .groupBy(articles.reporterId, users.firstName, users.lastName, users.profileImageUrl)
          .orderBy(sql`count(*) DESC`)
          .limit(1);

        if (!topAuthor || topAuthor.length === 0) {
          topAuthor = await db.select({
            userId: articles.authorId,
            count: sql<number>`count(*)::int`,
            firstName: users.firstName,
            lastName: users.lastName,
            profileImageUrl: users.profileImageUrl,
          })
            .from(articles)
            .innerJoin(users, eq(articles.authorId, users.id))
            .where(and(
              gte(articles.publishedAt, monthAgo),
              eq(articles.status, "published"),
              eq(articles.hideFromHomepage, false),
              or(isNull(articles.articleType), ne(articles.articleType, 'opinion')),
              isNotNull(articles.authorId)
            ))
            .groupBy(articles.authorId, users.firstName, users.lastName, users.profileImageUrl)
            .orderBy(sql`count(*) DESC`)
            .limit(1);
        }

        const [[totalViewsResult], [totalReactions], [totalBookmarks], [totalComments]] = await Promise.all([
          db.select({ total: sql<number>`COALESCE(SUM(${articles.views}), 0)::int` })
            .from(articles)
            .where(and(
              eq(articles.status, "published"),
              eq(articles.hideFromHomepage, false),
              or(isNull(articles.articleType), ne(articles.articleType, 'opinion'))
            )),
          db.select({ count: sql<number>`count(*)::int` }).from(reactions),
          db.select({ count: sql<number>`count(*)::int` }).from(bookmarks),
          db.select({ count: sql<number>`count(*)::int` }).from(comments),
        ]);

        const totalInteractions = (totalReactions?.count || 0) + 
                                  (totalBookmarks?.count || 0) + 
                                  (totalComments?.count || 0);

        const insights = {
          dailySummary: "منصة سبق الذكية تواصل تقديم أحدث الأخبار والتحليلات لقرائها",
          topTopics: [],
          activityTrend: growthPercentage > 5 ? "نمو ملحوظ في النشاط" : growthPercentage < -5 ? "انخفاض في النشاط" : "نشاط مستقر",
          keyHighlights: [
            `تم نشر ${todayC} خبراً اليوم`,
            topCategory[0] ? `تصنيف ${topCategory[0].name} الأكثر نشاطاً` : "تنوع في التصنيفات",
            `إجمالي ${totalInteractions.toLocaleString('en-US')} تفاعل`
          ]
        };

        return {
          period: { today: todayC, week: weekC, month: monthC },
          growth: {
            percentage: Math.round(growthPercentage * 10) / 10,
            trend: growthPercentage > 0 ? 'up' : growthPercentage < 0 ? 'down' : 'stable',
            previousMonth: prevMonthC,
          },
          topCategory: topCategory[0] ? {
            name: topCategory[0].name,
            icon: topCategory[0].icon,
            color: topCategory[0].color,
            count: topCategory[0].count,
          } : null,
          topAuthor: topAuthor[0] ? {
            name: `${topAuthor[0].firstName || ''} ${topAuthor[0].lastName || ''}`.trim(),
            profileImageUrl: topAuthor[0].profileImageUrl,
            count: topAuthor[0].count,
          } : null,
          totalViews: totalViewsResult.total || 0,
          totalInteractions,
          aiInsights: insights,
        };
      });

      res.json(analyticsData);
    } catch (error) {
      console.error("Error fetching news analytics:", error);
      res.status(500).json({ message: "Failed to fetch news analytics" });
    }
  });

