  app.post("/api/articles/:slug/comments", isAuthenticated, checkUserStatus(), async (req: any, res) => {
    try {
      const userId = req.user.id;
      const userRole = req.user.role;
      let article = await storage.getArticleBySlug(req.params.slug, userId, userRole);

      // Slug-or-id fallback: opinion pages (and any UUID-form article URL) post
      // by article id, but getArticleBySlug only matches slug/englishSlug, so
      // every such comment 404'd with "Article not found" for all users. Mirror
      // the UUID fallback the GET /api/articles/:slug route already uses.
      if (!article && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(req.params.slug)) {
        article = await storage.getArticleById(req.params.slug, userId);
      }

      if (!article) {
        return res.status(404).json({ message: "Article not found" });
      }

      const parsed = insertCommentSchema.safeParse({
        ...req.body,
        articleId: article.id,
        userId,
        platform: "web",
      });

      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid comment data" });
      }

      // فحص الكلمات المشبوهة قبل إنشاء التعليق
      const suspiciousCheck = await checkTextForSuspiciousWords(parsed.data.content);
      let blockedBySuspiciousWords = false;
      if (suspiciousCheck.hasSuspiciousWords) {
        console.log(`[Comments] Suspicious words detected: ${suspiciousCheck.foundWords.map(w => w.word).join(", ")}`);
        blockedBySuspiciousWords = true;
      }

      const comment = await storage.createComment(parsed.data);
      
      // إبطال كاش التعليقات فوراً عند إنشاء تعليق جديد
      const articleSlug = article.slug || req.params.slug;
      memoryCache.delete(`article:comments:${articleSlug}`);
      if (article.englishSlug) {
        memoryCache.delete(`article:comments:${article.englishSlug}`);
      }
      console.log(`[Comments] Cache invalidated for article: ${articleSlug}`);

      // معالجة الكلمات المشبوهة - رفض تلقائي أو تعليق للمراجعة حسب إعداد كل كلمة
      if (blockedBySuspiciousWords && suspiciousCheck.foundWords.length > 0) {
        const foundWordsStr = suspiciousCheck.foundWords.map(w => w.word).join(", ");
        const wordIds = suspiciousCheck.foundWords.map(w => w.wordId);
        const autoReject = suspiciousCheck.shouldAutoReject;
        const rejectingWords = suspiciousCheck.foundWords.filter(w => w.action === "reject").map(w => w.word);

        await storage.updateCommentStatus(comment.id, {
          status: autoReject ? "rejected" : "pending",
          moderatedAt: autoReject ? new Date() : undefined,
          moderationReason: autoReject
            ? `رُفض تلقائياً - كلمات محظورة: ${rejectingWords.join(", ")}`
            : `يحتوي على كلمات مشبوهة: ${foundWordsStr}`,
        });

        await incrementSuspiciousWordFlagCount(wordIds);

        console.log(
          `[Comments] Comment ${comment.id} ${autoReject ? "auto-rejected" : "held for review"} due to suspicious words: ${foundWordsStr}`
        );
      }

      // إضافة نقطة ولاء للتعليق
      try {
        await awardPoints({
          userId,
          action: LOYALTY_ACTIONS.COMMENT,
          source: article.id,
          metadata: { articleId: article.id, commentId: comment.id },
        });
      } catch (error) {
        console.error("Error recording loyalty points:", error);
      }


      // AI Moderation - تحليل التعليق بالذكاء الاصطناعي (background task)
      const commentId = comment.id;
      const commentContent = comment.content;
      const slugForCache = articleSlug;
      const suspiciousWordsData = blockedBySuspiciousWords ? suspiciousCheck : null;
      const englishSlugForCache = article.englishSlug;
      (async () => {
    try {
          const { moderateComment, getStatusFromClassification } = await import("./ai/commentModeration");
          const moderationResult = await moderateComment(commentContent);
          
          // Update moderation data
          await storage.updateCommentModeration(commentId, {
            aiModerationScore: moderationResult.score,
            aiClassification: moderationResult.classification,
            aiDetectedIssues: moderationResult.detected,
            aiModerationReason: moderationResult.reason,
            aiAnalyzedAt: new Date(),
          });
          
          // Update comment status based on AI classification
          // إذا كان التعليق يحتوي على كلمات محظورة (action=reject) فهو مرفوض بالفعل ولا يُعاد لـ pending
          // وإذا كان يحتوي على كلمات مشبوهة (action=review) يبقى معلقاً للمراجعة
          const aiStatus = getStatusFromClassification(moderationResult.classification);
          const wasAutoRejected = suspiciousWordsData?.shouldAutoReject;
          const newStatus = wasAutoRejected ? "rejected" : (suspiciousWordsData ? "pending" : aiStatus);
          if (newStatus !== "pending" && !wasAutoRejected) {
            await storage.updateCommentStatus(commentId, {
              status: newStatus,
              moderatedAt: new Date(),
              moderationReason: moderationResult.classification === "safe" 
                ? "تم الاعتماد تلقائياً بواسطة الذكاء الاصطناعي"
                : `تم الرفض تلقائياً - ${moderationResult.reason}`,
            });
            
            // إبطال كاش التعليقات بعد تحديث الحالة (مهم للاعتماد الأوتوماتيكي)
            memoryCache.delete(`article:comments:${slugForCache}`);
            if (englishSlugForCache) {
              memoryCache.delete(`article:comments:${englishSlugForCache}`);
            }
            console.log(`[AI Moderation] Cache invalidated after auto-${newStatus} for article: ${slugForCache}`);
          }
          
          // إذا كان التعليق يحتوي على كلمات مشبوهة، سجل ذلك وزد العداد
          if (suspiciousWordsData && suspiciousWordsData.foundWords.length > 0) {
            
            // تحديث سبب الرقابة ليشمل الكلمات المشبوهة
            const foundWordsStr = suspiciousWordsData.foundWords.map(w => w.word).join(", ");
            await storage.updateCommentModeration(commentId, {
              aiDetectedIssues: [...(moderationResult.detected || []), `كلمات مشبوهة: ${foundWordsStr}`],
              aiModerationReason: `يحتوي على كلمات مشبوهة: ${foundWordsStr}` + (moderationResult.reason ? ` - ${moderationResult.reason}` : ""),
            });
            console.log(`[AI Moderation] Comment ${commentId} held for suspicious words: ${foundWordsStr}`);
          }
          
          console.log(`[AI Moderation] Comment ${commentId} analyzed: ${moderationResult.classification} (${moderationResult.score}%) -> status: ${newStatus}`);
        } catch (error) {
          console.error("[AI Moderation] Error analyzing comment:", error);
        }
      })();


      // Track user event for daily summary analytics
    try {
        await trackUserEvent({
          userId,
          articleId: article.id,
          eventType: 'comment',
        });
      } catch (error) {
        console.error("Error tracking comment event:", error);
      }

      res.json(comment);
    } catch (error) {
      console.error("Error creating comment:", error);
      res.status(500).json({ message: "Failed to create comment" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights

  // Edit + Smart Content Generation Endpoint (rewrites content in Sabq style then generates all fields)
  app.post("/api/articles/edit-and-generate", isAuthenticated, requireAnyPermission('articles.create', 'articles.edit_any', 'articles.edit_own'), async (req: any, res) => {
    try {
      const { content, language = "ar" } = req.body;

      if (!content || typeof content !== 'string' || content.trim().length === 0) {
        return res.status(400).json({ message: "يجب توفير محتوى الخبر" });
      }

      console.log("[Edit+Generate API] Processing with parallel AI calls for best quality...");
      
      // Get available categories for better AI classification
      const allCategories = await storage.getAllCategories();
      const categoryList = allCategories.map(c => ({ nameAr: c.nameAr, nameEn: c.nameEn || c.nameAr }));
      
      // Run three operations in parallel for better quality:
      // 1. Smart content generation from ORIGINAL content (same as "توليد ذكي شامل")
      // 2. Editorial rewrite separately
      // 3. Newsletter subtitle/excerpt generation
      const { analyzeAndEditWithSabqStyle } = await import("./ai/contentAnalyzer");
      
      // Import retry helper for rate limit handling
      const { withRetry } = await import("./openai");

      // Run the three AI calls IN PARALLEL — they all consume the same original
      // `content` with no inter-dependency, so total latency drops from the sum of
      // three calls to just the slowest one (the Claude rewrite). Each call keeps
      // its own retry/backoff, which absorbs the occasional 429 under concurrency.
      // The newsletter subtitle is optional: its failure must not fail the request,
      // so it resolves to empty values instead of rejecting the Promise.all.
      console.log("[Edit+Generate API] Running smart content + Sabq edit + newsletter in parallel...");
      const [generatedContent, editResult, newsletterResult] = await Promise.all([
        withRetry(
          () => generateSmartContent(content, language as "ar" | "en"),
          3,
          "SmartContent"
        ),
        withRetry(
          () => analyzeAndEditWithSabqStyle(content, language as "ar" | "en" | "ur", categoryList),
          3,
          "EditContent"
        ),
        withRetry(
          () => generateNewsletterSubtitle({
            title: content.substring(0, 200),
            content: content,
            excerpt: undefined
          }),
          3,
          "Newsletter"
        ).catch((err): { subtitle: string | undefined; excerpt: string | undefined } => {
          console.warn("[Edit+Generate API] Newsletter generation failed (optional):", err);
          return { subtitle: undefined, excerpt: undefined };
        }),
      ]);

      console.log("[Edit+Generate API] ✅ All operations completed");
      console.log("[Edit+Generate API] Quality score:", editResult.qualityScore);
      console.log("[Edit+Generate API] Title (Claude→GPT fallback):", editResult.optimized.title || generatedContent.mainTitle);
      console.log("[Edit+Generate API] Newsletter subtitle:", newsletterResult?.subtitle || "N/A");
      
      // Return combined result with best of both worlds
      res.json({
        // Rewritten content from Sabq editor
        editedContent: editResult.optimized.content,
        editedLead: editResult.optimized.lead,
        qualityScore: editResult.qualityScore,
        detectedCategory: editResult.detectedCategory,
        hasNewsValue: editResult.hasNewsValue,
        issues: editResult.issues,
        suggestions: editResult.suggestions,
        // العنوان من محرر الأسلوب المعتمد (Claude) — وعنوان GPT احتياطاً عند فشله
        mainTitle: editResult.optimized.title || generatedContent.mainTitle,
        subTitle: generatedContent.subTitle,
        smartSummary: generatedContent.smartSummary,
        keywords: generatedContent.keywords,
        seo: generatedContent.seo,
        // Newsletter fields
        newsletterSubtitle: newsletterResult.subtitle,
        newsletterExcerpt: newsletterResult.excerpt,
      });
    } catch (error: any) {
      console.error("[Edit+Generate API] ❌ Error occurred:");
      console.error("[Edit+Generate API] Error name:", error?.name);
      console.error("[Edit+Generate API] Error message:", error?.message);
      console.error("[Edit+Generate API] Error status:", error?.status);
      console.error("[Edit+Generate API] Error code:", error?.code);
      console.error("[Edit+Generate API] Full error:", JSON.stringify(error, null, 2));
      
      // Determine error type for appropriate response
      const isRateLimit = error?.status === 429 || 
                          error?.message?.includes("429") || 
                          error?.message?.includes("rate limit") ||
                          error?.message?.includes("Rate limit");
      const isTimeout = error?.message?.includes("timeout") || error?.code === 'ETIMEDOUT';
      const isNetwork = error?.code === 'ECONNREFUSED' || error?.code === 'ENOTFOUND';
      
      let statusCode = 500;
      let message = "فشل في تحرير وتوليد المحتوى";
      
      if (isRateLimit) {
        statusCode = 429;
        message = "تم تجاوز حد الطلبات، يرجى المحاولة بعد دقيقة";
      } else if (isTimeout) {
        statusCode = 504;
        message = "انتهت مهلة الاتصال، يرجى المحاولة مرة أخرى";
      } else if (isNetwork) {
        statusCode = 503;
        message = "خطأ في الاتصال بخدمة الذكاء الاصطناعي";
      }
      
      res.status(statusCode).json({ 
        message,
        errorType: isRateLimit ? "rate_limit" : isTimeout ? "timeout" : isNetwork ? "network" : "unknown",
        details: process.env.NODE_ENV === 'development' ? error?.message : undefined
      });
    }
  });

