  // PATCH /api/media-assets/:id - Update media asset
  app.patch("/api/media-assets/:id",
    requireAuth,
    // Was requireRole("reporter","editor","admin") — a fixed role-name guard
    // that 403s accounts whose real roles come from user_roles under a different
    // name (legacy role-text trap). Gate on the equivalent permissions instead.
    requireAnyPermission("articles.edit_own", "articles.edit_any", "media.edit"),
    async (req: any, res) => {
    try {
        const { id } = req.params;
        
        const parsed = updateArticleMediaAssetSchema.safeParse(req.body);

        if (!parsed.success) {
          return res.status(400).json({ 
            message: "Invalid data", 
            errors: parsed.error.errors 
          });
        }
        
        const dataToUpdate = {
          ...parsed.data,
          altText: parsed.data.altText || "صورة الخبر",
        };
        const asset = await storage.updateArticleMediaAsset(id, dataToUpdate);

        if (!asset) {
          return res.status(404).json({ message: "Media asset not found" });
        }

        memoryCache.invalidatePattern('^article:media-assets:');
        const articleForPurge = await storage.getArticleById(asset.articleId);
        if (articleForPurge) {
          invalidateArticleWrite(articleForPurge, { reason: 'media-asset-update' });
        }
        res.json(asset);
      } catch (error: any) {
        console.error("Error updating media asset:", error);
        res.status(500).json({ message: "Failed to update media asset" });
      }
    }
  );

  // DELETE /api/media-assets/:id - Delete media asset
  app.delete("/api/media-assets/:id",
    requireAuth,
    // Was requireRole("editor","admin") — see PATCH note (legacy role-text trap).
    requireAnyPermission("articles.edit_any", "media.delete"),
    async (req: any, res) => {
    try {
        const { id } = req.params;

        // Look up asset BEFORE deleting so we can purge the right article URLs.
        const existing = await storage.getArticleMediaAssetById(id);
        await storage.deleteArticleMediaAsset(id);

        memoryCache.invalidatePattern('^article:media-assets:');
        if (existing?.articleId) {
          const articleForPurge = await storage.getArticleById(existing.articleId);
          if (articleForPurge) {
            invalidateArticleWrite(articleForPurge, { reason: 'media-asset-delete' });
          }
        }
        res.status(204).send();
      } catch (error: any) {
        console.error("Error deleting media asset:", error);
        res.status(500).json({ message: "Failed to delete media asset" });
      }
    }
  );

