  app.post("/api/dashboard/articles", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = await storage.getUser(userId);

      if (!user || (user.role !== "editor" && user.role !== "admin" && user.role !== "reporter")) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const requestData = { ...req.body, authorId: userId };
      if (requestData.publishedAt && typeof requestData.publishedAt === 'string') {
        requestData.publishedAt = new Date(requestData.publishedAt);
      }
      if (requestData.scheduledAt && typeof requestData.scheduledAt === 'string') {
        requestData.scheduledAt = new Date(requestData.scheduledAt);
      }

      // Check scheduling permission
      if (requestData.scheduledAt) {
        const hasSchedulePerm = await userHasPermission(req.user.id, PERMISSION_CODES.ARTICLES_SCHEDULE);
        if (!hasSchedulePerm) {
          return res.status(403).json({ message: "لا توجد لديك صلاحيات لجدولة المقالات" });
        }
      }

      if (requestData.content && typeof requestData.content === "string") {
        requestData.content = sanitizeArticleHtml(requestData.content);
      }

      const parsed = insertArticleSchema.safeParse(requestData);

      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid article data", errors: parsed.error });
      }

      const article = await storage.createArticle(parsed.data);

      // Invalidate caches (in-memory + Redis pub/sub + Cloudflare CDN purge)
      // for instant visibility of the new article across all pods + edge.
      invalidateArticleWrite(article, { reason: 'dashboard-create' });
      memoryCache.delete('lite-feed');

      console.log(`🔍 [DASHBOARD CREATE] Article created with status: ${article.status}`);
      console.log(`🔍 [DASHBOARD CREATE] Article ID: ${article.id}, Title: ${article.title}`);
      
      // Send notification to editors when a reporter submits a draft
      if (article.status === 'draft' && article.reporterId) {
        setImmediate(async () => {
          try {
            // Get reporter name
            const [reporter] = await db
              .select({ firstName: users.firstName, lastName: users.lastName })
              .from(users)
              .where(eq(users.id, article.reporterId!))
              .limit(1);
            
            const reporterName = reporter 
              ? [reporter.firstName, reporter.lastName].filter(Boolean).join(' ') || 'مراسل'
              : 'مراسل';
            
            await sendDraftSubmittedNotification(
              { id: article.id, title: article.title, slug: article.slug },
              reporterName,
              article.reporterId!
            );
            
            // Log activity for draft submission
            await logActivity({
              userId: article.reporterId!,
              action: 'draft_submitted',
              entityType: 'article',
              entityId: article.id,
              metadata: {
                articleTitle: article.title,
                reporterName,
              },
            });
          } catch (err) {
            console.error("[DRAFT NOTIFY] Error:", err);
          }
        });
      }

      
      // CRITICAL: Notify reporter IMMEDIATELY before response (must survive server restarts)
      if (article.status === "published") {
        try {
          console.log(`📰 [DASHBOARD CREATE] Sending reporter notification BEFORE response...`);
          await notifyReporterArticlePublished(article.id);
          // Send email notification to reporter
          await sendReporterPublishEmail(article.id);
          console.log(`✅ [DASHBOARD CREATE] Reporter notification queued successfully`);
        } catch (reporterNotifyError) {
          console.error("❌ [DASHBOARD CREATE] Error notifying reporter:", reporterNotifyError);
        }
      }
      
      // Return response immediately to user
      res.json(article);

      // Broadcast publish event to other editors via SSE
      if (article.status === 'published') {
        try {
          const publisherName =
            [user?.firstName, user?.lastName].filter(Boolean).join(' ').trim() ||
            user?.email ||
            'محرر';
          broadcastArticlePublished({
            articleId: article.id,
            articleTitle: article.title,
            articleSlug: article.slug || null,
            publisherName,
            publishedAt: (article.publishedAt instanceof Date
              ? article.publishedAt
              : new Date()).toISOString(),
          });
        } catch (err) {
          console.error('[EditorPresence] broadcast publish failed:', err);
        }
      }

      // Log article created event (fire-and-forget)
      logArticleEvent({
        articleId: article.id,
        eventType: 'created',
        actorId: req.user?.id,
        summary: 'تم إنشاء الخبر',
      }).catch(err => console.error("[DASHBOARD CREATE] Failed to log event:", err));

      // Log published event if article was created as published
      if (article.status === 'published') {
        logArticleEvent({
          articleId: article.id,
          eventType: 'published',
          actorId: req.user?.id,
          summary: 'تم نشر الخبر',
        }).catch(err => console.error("[DASHBOARD CREATE] Failed to log publish event:", err));
      }
      // IndexNow ping (Bing/Yandex). Submit the canonical englishSlug URL.
      if (article.status === 'published' && (article.englishSlug || article.slug)) {
        notifySearchEngines(article.englishSlug || article.slug).catch(() => {});
      }

      // Process async operations in background (non-blocking)
      if (article.status === "published") {
        console.log(`🔔 [DASHBOARD CREATE] Article is PUBLISHED - processing notifications in background...`);
        
        // Run async operations without blocking the response
        setImmediate(async () => {
    try {
            // Determine notification type based on newsType
            let notificationType: 'published' | 'breaking' | 'featured' = 'published';
            if (article.newsType === 'breaking') {
              notificationType = 'breaking';
            } else if (article.newsType === 'featured') {
              notificationType = 'featured';
            }

            console.log(`🔔 [DASHBOARD CREATE] Calling sendArticleNotification with type: ${notificationType}`);
            
            // Send smart notifications via notification service
            await sendArticleNotification(article, notificationType);

            console.log(`✅ [DASHBOARD CREATE] Notifications sent for new article: ${article.title}`);

            // Send editor-in-chief publish alert
            (async () => {
            const publisherName = await getPublisherName(req.user?.id);
            await sendEditorPublishAlert({
              id: article.id,
              title: article.title,
              slug: article.slug,
              englishSlug: article.englishSlug || undefined,
              authorName: publisherName,
              publishedAt: article.publishedAt || undefined,
            });
          })().catch(err => console.error("[EditorAlerts] Error:", err));

            // Generate article embeddings for recommendation system
    try {
              await vectorizeArticle(article.id);
              console.log(`✅ [DASHBOARD CREATE] Article vectorized for recommendations: ${article.title}`);
            } catch (vectorizationError) {
              console.error("❌ [DASHBOARD CREATE] Error vectorizing article:", vectorizationError);
              // Don't fail the article creation if vectorization fails
            }

            // Auto-link article to story using AI
    try {
              const { matchAndLinkArticle } = await import("./storyMatcher");
              await matchAndLinkArticle(article.id);
              console.log(`✅ [DASHBOARD CREATE] Article auto-linked to story: ${article.title}`);
            } catch (storyMatchError) {
              console.error("❌ [DASHBOARD CREATE] Error linking article to story:", storyMatchError);
              // Don't fail the article creation if story matching fails
            }

            // Keep old system for backward compatibility
            await createNotification({
              type: article.newsType === "breaking" ? "BREAKING_NEWS" : "NEW_ARTICLE",
              data: {
                articleId: article.id,
                articleTitle: article.title,
                articleSlug: article.slug,
                categoryId: article.categoryId,
                newsType: article.newsType,
              },
            });
            // Reporter notification moved to before res.json() to survive server restarts
          } catch (notificationError) {
            console.error("❌ [DASHBOARD CREATE] Error creating notification:", notificationError);
            // Don't fail the article creation if notification fails
          }
        });
      } else {
        console.log(`⏸️ [DASHBOARD CREATE] Article is NOT published (status: ${article.status}) - skipping notifications`);
      }
    } catch (error) {
      console.error("Error creating article:", error);
      res.status(500).json({ message: "Failed to create article" });
    }
  });

