  // Dashboard: Create new opinion article
  app.post("/api/dashboard/opinion", requireAuth, requirePermission("articles.create"), async (req: any, res) => {
    try {
      const authorId = req.user?.id;
      if (!authorId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const requestData = { ...req.body, articleType: "opinion" };
      if (requestData.content && typeof requestData.content === "string") {
        requestData.content = sanitizeArticleHtml(requestData.content);
      }
      const parsed = insertArticleSchema.safeParse(requestData);

      if (!parsed.success) {
        return res.status(400).json({
          message: "Invalid article data",
          errors: parsed.error.flatten(),
        });
      }

      const articleData: any = {
        ...parsed.data,
        authorId,
        articleType: "opinion",
        // Opinion creation previously left englishSlug NULL (unlike regular
        // article creation, routes.ts ~6920). A NULL englishSlug means the
        // article is only reachable via its Arabic slug and gets an
        // Arabic-slug canonical — a recurring source of the GSC duplicate /
        // non-canonical buckets. Generate one on create, same as articles.
        englishSlug: parsed.data.englishSlug || generateEnglishSlug(parsed.data.title),
      };

      const [newArticle] = await db
        .insert(articles)
        .values(articleData)
        .returning();

      await logActivity({
        userId: authorId,
        action: "created_opinion",
        entityType: "article",
        entityId: newArticle.id,
        newValue: newArticle,
        metadata: {
          ip: req.ip,
          userAgent: req.get("user-agent"),
        },
      });

      // Log article created event
      logArticleEvent({
        articleId: newArticle.id,
        eventType: 'created',
        actorId: req.user?.id,
        summary: 'تم إنشاء الخبر',
      }).catch(err => console.error("[CREATE ARTICLE] Failed to log event:", err));

      // Log published event if article was created as published
      if (newArticle.status === 'published') {
        logArticleEvent({
          articleId: newArticle.id,
          eventType: 'published',
          actorId: req.user?.id,
          summary: 'تم نشر الخبر',
        }).catch(err => console.error("[CREATE ARTICLE] Failed to log publish event:", err));
      }

      res.status(201).json(newArticle);
    } catch (error) {
      console.error("Error creating opinion article:", error);
      res.status(500).json({ message: "Failed to create opinion article" });
    }
  });

