  // Dashboard: Update opinion article
  app.patch("/api/dashboard/opinion/:id", requireAuth, async (req: any, res) => {
    try {
      const userId = req.user?.id;
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const articleId = req.params.id;

      const [existingArticle] = await db
        .select()
        .from(articles)
        .where(
          and(
            eq(articles.id, articleId),
            eq(articles.articleType, "opinion")
          )
        )
        .limit(1);

      if (!existingArticle) {
        return res.status(404).json({ message: "Opinion article not found" });
      }

      // Check permissions
      const userPermissions = await getUserPermissions(userId);
      const canEditOwn = userPermissions.includes("opinion.edit_own");
      const canEditAny = userPermissions.includes("opinion.edit_any");

      if (!canEditAny && (!canEditOwn || existingArticle.authorId !== userId)) {
        return res.status(403).json({ message: "You don't have permission to edit this opinion article" });
      }

      const sanitizedBody = sanitizeArticleUpdatePayload(req.body);
      const parsed = updateArticleSchema.safeParse(sanitizedBody);

      if (!parsed.success) {
        console.error("[OPINION ARTICLE UPDATE] Validation failed:", JSON.stringify(parsed.error.flatten(), null, 2));
        console.error("[OPINION ARTICLE UPDATE] Request body keys:", Object.keys(req.body));
        return res.status(400).json({
          message: "Invalid data",
          errors: parsed.error.flatten(),
        });
      }

      // Convert all timestamp fields from strings to Date objects if provided
      const updateData: any = { ...parsed.data };
      
      // Convert timestamp fields (if they exist and are strings)
      const timestampFields = ['publishedAt', 'scheduledAt'];
      timestampFields.forEach(field => {
        if (updateData[field] && typeof updateData[field] === 'string') {
          updateData[field] = new Date(updateData[field]);
        }
      });

      const [updatedArticle] = await db
        .update(articles)
        .set({
          ...updateData,
          updatedAt: new Date(),
        })
        .where(eq(articles.id, articleId))
        .returning();

      await logActivity({
        userId,
        action: "updated_opinion",
        entityType: "article",
        entityId: articleId,
        oldValue: existingArticle,
        newValue: updatedArticle,
        metadata: {
          ip: req.ip,
          userAgent: req.get("user-agent"),
        },
      });

      // Invalidate cache and broadcast to all connected clients for instant update
      invalidatePublishedContent({ reason: "article-write" });
      memoryCache.delete('lite-feed'); // Clear mobile app feed cache
      memoryCache.invalidatePattern('^article:detail:');
      memoryCache.invalidatePattern('^article:id:');
      memoryCache.invalidatePattern('^articles:');
      memoryCache.invalidatePattern('^sidebar:');
      console.log(`[Breaking News] Cache invalidated and SSE broadcast sent for article ${articleId}`);

      res.json(updatedArticle);
    } catch (error) {
      console.error("Error updating opinion article:", error);
      res.status(500).json({ message: "Failed to update opinion article" });
    }
  });

