  app.post("/api/dashboard/opinion/:id/request-revision", requireAuth, requirePermission("articles.edit_any"), async (req: any, res) => {
    try {
      const userId = req.user?.id;
      if (!userId) return res.status(401).json({ message: "Unauthorized" });

      const articleId = req.params.id;
      const { reviewNotes } = req.body;
      if (!reviewNotes || typeof reviewNotes !== "string") {
        return res.status(400).json({ message: "Review notes are required when requesting revision" });
      }

      const [existingArticle] = await db
        .select()
        .from(articles)
        .where(eq(articles.id, articleId))
        .limit(1);

      if (!existingArticle) {
        return res.status(404).json({ message: "Article not found" });
      }

      const [updatedArticle] = await db
        .update(articles)
        .set({
          reviewStatus: "needs_changes",
          reviewedBy: userId,
          reviewedAt: new Date(),
          reviewNotes,
          status: "draft",
          updatedAt: new Date(),
        })
        .where(eq(articles.id, articleId))
        .returning();

      res.json(updatedArticle);

      // Fire-and-forget push notification — same trigger path as the
      // PATCH route, but invoked explicitly here since this dedicated
      // endpoint bypasses the generic update flow.
      setImmediate(async () => {
        try {
          await notifyArticleStakeholders({
            id: updatedArticle.id,
            title: updatedArticle.title,
            slug: updatedArticle.slug,
            englishSlug: updatedArticle.englishSlug,
            articleType: updatedArticle.articleType,
            scheduledAt: updatedArticle.scheduledAt,
            publishedAt: updatedArticle.publishedAt,
            authorId: updatedArticle.authorId,
            reporterId: updatedArticle.reporterId,
            submitterId: updatedArticle.submitterId,
          }, "needs_revision", reviewNotes);
          if (updatedArticle.articleType === "opinion") {
            await sendOpinionAuthorRevisionEmail(updatedArticle.id, reviewNotes);
          } else {
            await sendReporterRevisionEmail(updatedArticle.id, reviewNotes);
          }
        } catch (notifyErr: any) {
          console.error("[OpinionRevision] push notify failed:", notifyErr?.message || notifyErr);
        }
      });
    } catch (error) {
      console.error("Error requesting revision on opinion article:", error);
      res.status(500).json({ message: "Failed to request revision" });
    }
  });

  // News Analytics Endpoint - Smart statistics and insights

  // Dashboard: Delete opinion article
  app.delete("/api/dashboard/opinion/:id", requireAuth, async (req: any, res) => {
    try {
      const userId = req.user?.id;
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const articleId = req.params.id;

      const [existingArticle] = await db
        .select()
        .from(articles)
        .where(
          and(
            eq(articles.id, articleId),
            eq(articles.articleType, "opinion")
          )
        )
        .limit(1);

      if (!existingArticle) {
        return res.status(404).json({ message: "Opinion article not found" });
      }

      // Check permissions
      const userPermissions = await getUserPermissions(userId);
      const canDeleteOwn = userPermissions.includes("opinion.delete_own");
      const canDeleteAny = userPermissions.includes("opinion.delete_any");

      if (!canDeleteAny && (!canDeleteOwn || existingArticle.authorId !== userId)) {
        return res.status(403).json({ message: "You don't have permission to delete this opinion article" });
      }

      // Soft delete by archiving
      const [updatedArticle] = await db
        .update(articles)
        .set({
          status: "archived",
          updatedAt: new Date(),
        })
        .where(eq(articles.id, articleId))
        .returning();

      await logActivity({
        userId,
        action: "deleted_opinion",
        entityType: "article",
        entityId: articleId,
        oldValue: existingArticle,
        newValue: updatedArticle,
        metadata: {
          ip: req.ip,
          userAgent: req.get("user-agent"),
        },
      });

      res.json({ message: "Opinion article deleted successfully" });
    } catch (error) {
      console.error("Error deleting opinion article:", error);
      res.status(500).json({ message: "Failed to delete opinion article" });
    }
  });

