  // Stable hash-bucketed article sitemaps:
  // articles partitioned by abs(hashtext(id::text)) % N, lastmod from
  // updated_at || published_at. Bucket assignment is stable for a given id.
  const SITEMAP_AR_BUCKETS = 50;
  const SITEMAP_EN_BUCKETS = 10;
  const SITEMAP_UR_BUCKETS = 10;

  // Dynamic XML Sitemap Index
  app.get("/sitemap.xml", async (_req, res) => {
    try {
      const baseUrl = "https://sabq.org";
      const now = Date.now();
      const cache = (app as any).__sitemapIndexCache;
      if (cache && now - cache.ts < 30 * 60 * 1000) {
        res.header('Content-Type', 'application/xml; charset=utf-8');
        res.setHeader('Cache-Control', 'public, max-age=1800, s-maxage=1800');
        return res.send(cache.xml);
      }

      // Most-recent published article → a <lastmod> hint on the
      // frequently-changing news + article-bucket children so Google
      // reprioritizes them on recrawl. One cheap aggregate; index is cached 10m.
      let lastmod = '';
      try {
        const r = await db.execute(sql`SELECT MAX(published_at) AS m FROM articles WHERE status = 'published'`);
        const m = (((r as any).rows || r)[0] || {}).m;
        if (m) lastmod = `<lastmod>${new Date(m).toISOString()}</lastmod>`;
      } catch { /* lastmod is best-effort */ }

      let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
      xml += '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
      xml += `  <sitemap><loc>${baseUrl}/sitemap-static.xml</loc></sitemap>\n`;
      xml += `  <sitemap><loc>${baseUrl}/sitemap-categories.xml</loc>${lastmod}</sitemap>\n`;
      xml += `  <sitemap><loc>${baseUrl}/sitemap-news.xml</loc>${lastmod}</sitemap>\n`;
      for (let i = 1; i <= SITEMAP_AR_BUCKETS; i++) {
        xml += `  <sitemap><loc>${baseUrl}/sitemap-articles-${i}.xml</loc>${lastmod}</sitemap>\n`;
      }
      for (let i = 1; i <= SITEMAP_EN_BUCKETS; i++) {
        xml += `  <sitemap><loc>${baseUrl}/sitemap-en-articles-${i}.xml</loc>${lastmod}</sitemap>\n`;
      }
      for (let i = 1; i <= SITEMAP_UR_BUCKETS; i++) {
        xml += `  <sitemap><loc>${baseUrl}/sitemap-ur-articles-${i}.xml</loc>${lastmod}</sitemap>\n`;
      }
      xml += '</sitemapindex>';

      (app as any).__sitemapIndexCache = { xml, ts: now };
      res.header('Content-Type', 'application/xml; charset=utf-8');
      res.setHeader('Cache-Control', 'public, max-age=1800, s-maxage=1800');
      res.send(xml);
    } catch (error) {
      console.error("Error generating sitemap index:", error);
      res.status(500).send("Error generating sitemap");
    }
  });

  app.get("/sitemap-static.xml", (_req, res) => {
    const baseUrl = "https://sabq.org";
    let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
    xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
    xml += `  <url><loc>${baseUrl}</loc><changefreq>hourly</changefreq><priority>1.0</priority></url>\n`;
    xml += `  <url><loc>${baseUrl}/en</loc><changefreq>hourly</changefreq><priority>0.9</priority></url>\n`;
    xml += `  <url><loc>${baseUrl}/ur</loc><changefreq>hourly</changefreq><priority>0.8</priority></url>\n`;
    xml += `  <url><loc>${baseUrl}/world-cup</loc><changefreq>hourly</changefreq><priority>0.8</priority></url>\n`;
    for (const page of ['/gulf-live', '/world-days']) {
      xml += `  <url><loc>${baseUrl}${page}</loc><changefreq>daily</changefreq><priority>0.5</priority></url>\n`;
    }
    for (const page of ['/about', '/privacy', '/terms', '/contact', '/rss', '/categories', '/opinion', '/shorts', '/daily-brief']) {
      xml += `  <url><loc>${baseUrl}${page}</loc><changefreq>monthly</changefreq><priority>0.3</priority></url>\n`;
    }
    xml += '</urlset>';
    res.header('Content-Type', 'application/xml; charset=utf-8');
    res.setHeader('Cache-Control', 'public, max-age=3600, s-maxage=3600');
    res.send(xml);
  });

  app.get("/sitemap-categories.xml", async (_req, res) => {
    try {
      const baseUrl = "https://sabq.org";
      const now = Date.now();
      const cache = (app as any).__sitemapCatsCache;
      if (cache && now - cache.ts < 30 * 60 * 1000) {
        res.header('Content-Type', 'application/xml; charset=utf-8');
        res.setHeader('Cache-Control', 'public, max-age=1800, s-maxage=1800');
        return res.send(cache.xml);
      }
      const activeCats = await db.execute(sql`
        SELECT c.slug, c.english_slug FROM categories c
        WHERE c.status = 'visible'
        AND EXISTS (SELECT 1 FROM articles a WHERE a.category_id = c.id AND a.status = 'published' LIMIT 1)
        ORDER BY c.display_order
      `);
      const catRows: any[] = (activeCats as any).rows || activeCats;

      let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
      xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
      for (const cat of catRows) {
        const catSlug = cat.english_slug || cat.slug;
        xml += `  <url><loc>${baseUrl}/category/${encodeURIComponent(catSlug)}</loc><changefreq>hourly</changefreq><priority>0.6</priority></url>\n`;
      }
      xml += '</urlset>';
      (app as any).__sitemapCatsCache = { xml, ts: now };
      res.header('Content-Type', 'application/xml; charset=utf-8');
      res.setHeader('Cache-Control', 'public, max-age=1800, s-maxage=1800');
      res.send(xml);
    } catch (error) {
      console.error("Error generating categories sitemap:", error);
      res.status(500).send("Error generating sitemap");
    }
  });

  type SitemapTableSpec = {
    table: typeof articles | typeof enArticles | typeof urArticles;
    id: typeof articles.id;
    slug: typeof articles.slug;
    englishSlug: typeof articles.englishSlug;
    title: typeof articles.title;
    publishedAt: typeof articles.publishedAt;
    updatedAt: typeof articles.updatedAt;
    status: typeof articles.status;
    imageUrl: typeof articles.imageUrl;
  };

  async function generateArticleSitemap(
    spec: SitemapTableSpec,
    pathPrefix: string,
    bucket: number,
    totalBuckets: number,
  ): Promise<string | null> {
    if (isNaN(bucket) || bucket < 1 || bucket > totalBuckets) return null;
    const baseUrl = "https://sabq.org";
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

    const rows = await db
      .select({
        slug: spec.slug,
        englishSlug: spec.englishSlug,
        title: spec.title,
        publishedAt: spec.publishedAt,
        updatedAt: spec.updatedAt,
        imageUrl: spec.imageUrl,
      })
      .from(spec.table)
      .where(
        and(
          eq(spec.status, "published"),
          isNotNull(spec.publishedAt),
          isNotNull(spec.title),
          ne(spec.title, ""),
          lte(spec.publishedAt, new Date()),
          sql`abs(hashtext(${spec.id}::text)) % ${totalBuckets} = ${bucket - 1}`,
        ),
      )
      .orderBy(desc(spec.publishedAt))
      .limit(50000);

    if (rows.length === 0) {
      // Return an empty (but well-formed) sitemap so the bucket URL keeps responding 200
      return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n</urlset>';
    }

    const xmlEscape = (s: string) => s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
    const absImg = (u: string | null | undefined) => {
      if (!u) return null;
      return /^https?:\/\//i.test(u) ? u : `${baseUrl}${u.startsWith('/') ? '' : '/'}${u}`;
    };

    let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
    xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"\n';
    xml += '        xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">\n';
    for (const row of rows) {
      const canonicalSlug = row.englishSlug || row.slug;
      if (!canonicalSlug) continue;
      const lastmodSource = row.updatedAt || row.publishedAt || new Date();
      const lastmod = new Date(lastmodSource).toISOString();
      const pubDate = row.publishedAt ? new Date(row.publishedAt) : new Date(0);
      let priority = '0.3';
      let changefreq = 'yearly';
      if (pubDate > sevenDaysAgo) { priority = '0.9'; changefreq = 'hourly'; }
      else if (pubDate > thirtyDaysAgo) { priority = '0.7'; changefreq = 'daily'; }
      const img = absImg(row.imageUrl);
      xml += `  <url>\n`;
      xml += `    <loc>${baseUrl}${pathPrefix}/${encodeURIComponent(canonicalSlug)}</loc>\n`;
      xml += `    <lastmod>${lastmod}</lastmod>\n`;
      xml += `    <changefreq>${changefreq}</changefreq>\n`;
      xml += `    <priority>${priority}</priority>\n`;
      if (img) {
        xml += `    <image:image><image:loc>${xmlEscape(img)}</image:loc></image:image>\n`;
      }
      xml += `  </url>\n`;
    }
    xml += '</urlset>';
    return xml;
  }

  function registerBucketedSitemap(
    routePath: string,
    cachePrefix: string,
    spec: SitemapTableSpec,
    pathPrefix: string,
    totalBuckets: number,
  ) {
    app.get(routePath, async (req, res) => {
      try {
        const bucket = parseInt(req.params.page, 10);
        if (isNaN(bucket) || bucket < 1 || bucket > totalBuckets) {
          return res.status(404).send("Not found");
        }

        const now = Date.now();
        const cacheKey = `${cachePrefix}_${bucket}`;
        const cache = (app as any)[cacheKey];
        if (cache && now - cache.ts < 30 * 60 * 1000) {
          res.header('Content-Type', 'application/xml; charset=utf-8');
          res.setHeader('Cache-Control', 'public, max-age=1800, s-maxage=1800');
          return res.send(cache.xml);
        }

        const xml = await generateArticleSitemap(spec, pathPrefix, bucket, totalBuckets);
        if (xml === null) return res.status(404).send("Not found");

        (app as any)[cacheKey] = { xml, ts: now };
        res.header('Content-Type', 'application/xml; charset=utf-8');
        res.setHeader('Cache-Control', 'public, max-age=1800, s-maxage=1800');
        res.send(xml);
      } catch (error) {
        console.error(`Error generating ${cachePrefix} sitemap:`, error);
        res.status(500).send("Error generating sitemap");
      }
    });
  }

  const arSitemapSpec: SitemapTableSpec = {
    table: articles,
    id: articles.id,
    slug: articles.slug,
    englishSlug: articles.englishSlug,
    title: articles.title,
    publishedAt: articles.publishedAt,
    updatedAt: articles.updatedAt,
    status: articles.status,
    imageUrl: articles.imageUrl,
  };
  const enSitemapSpec: SitemapTableSpec = {
    table: enArticles,
    id: enArticles.id,
    slug: enArticles.slug,
    englishSlug: enArticles.englishSlug,
    title: enArticles.title,
    publishedAt: enArticles.publishedAt,
    updatedAt: enArticles.updatedAt,
    status: enArticles.status,
    imageUrl: enArticles.imageUrl,
  } as any;
  const urSitemapSpec: SitemapTableSpec = {
    table: urArticles,
    id: urArticles.id,
    slug: urArticles.slug,
    englishSlug: urArticles.englishSlug,
    title: urArticles.title,
    publishedAt: urArticles.publishedAt,
    updatedAt: urArticles.updatedAt,
    status: urArticles.status,
    imageUrl: urArticles.imageUrl,
  } as any;

  registerBucketedSitemap("/sitemap-articles-:page.xml", "__sitemapArticles", arSitemapSpec, "/article", SITEMAP_AR_BUCKETS);
  registerBucketedSitemap("/sitemap-en-articles-:page.xml", "__sitemapEnArticles", enSitemapSpec, "/en/article", SITEMAP_EN_BUCKETS);
  registerBucketedSitemap("/sitemap-ur-articles-:page.xml", "__sitemapUrArticles", urSitemapSpec, "/ur/article", SITEMAP_UR_BUCKETS);

  // Google News sitemap: last 48h only. Spec: https://support.google.com/news/publisher-center/answer/9606710
  app.get("/sitemap-news.xml", async (req, res) => {
    try {
      const baseUrl = "https://sabq.org";
      const cutoff = new Date(Date.now() - 48 * 60 * 60 * 1000);

      const now = Date.now();
      const cache = (app as any).__sitemapNewsCache;
      if (cache && now - cache.ts < 3 * 60 * 1000) {
        res.header('Content-Type', 'application/xml; charset=utf-8');
        res.setHeader('Cache-Control', 'public, max-age=180, s-maxage=180');
        return res.send(cache.xml);
      }

      const now2 = new Date();
      type NewsTable = typeof articles | typeof enArticles | typeof urArticles;
      const baseFilter = (table: NewsTable) =>
        and(
          eq(table.status, "published"),
          isNotNull(table.publishedAt),
          isNotNull(table.title),
          ne(table.title, ""),
          gte(table.publishedAt, cutoff),
          lte(table.publishedAt, now2),
        );

      // Google News sitemap caps at 1,000 URLs total.
      const NEWS_SITEMAP_TOTAL_LIMIT = 1000;
      const NEWS_AR_LIMIT = 800;
      const NEWS_EN_LIMIT = 100;
      const NEWS_UR_LIMIT = 100;

      const [arRecent, enRecent, urRecent] = await Promise.all([
        db.select({
          slug: articles.slug,
          englishSlug: articles.englishSlug,
          title: articles.title,
          publishedAt: articles.publishedAt,
        }).from(articles).where(baseFilter(articles)).orderBy(desc(articles.publishedAt)).limit(NEWS_AR_LIMIT),
        db.select({
          slug: enArticles.slug,
          englishSlug: enArticles.englishSlug,
          title: enArticles.title,
          publishedAt: enArticles.publishedAt,
        }).from(enArticles).where(baseFilter(enArticles)).orderBy(desc(enArticles.publishedAt)).limit(NEWS_EN_LIMIT),
        db.select({
          slug: urArticles.slug,
          englishSlug: urArticles.englishSlug,
          title: urArticles.title,
          publishedAt: urArticles.publishedAt,
        }).from(urArticles).where(baseFilter(urArticles)).orderBy(desc(urArticles.publishedAt)).limit(NEWS_UR_LIMIT),
      ]);

      const totalCount = arRecent.length + enRecent.length + urRecent.length;
      if (totalCount > NEWS_SITEMAP_TOTAL_LIMIT) {
        console.warn(`[Sitemap-News] Total ${totalCount} exceeded 1000-URL cap; truncating`);
      }

      let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
      xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"\n';
      xml += '        xmlns:news="http://www.google.com/schemas/sitemap-news/0.9">\n';

      const escapeXml = (s: string) => s
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');

      const writeNewsEntry = (
        canonicalSlug: string,
        pathPrefix: string,
        title: string,
        publishedAt: Date | null,
        publicationName: string,
        language: string,
      ) => {
        if (!canonicalSlug || !title) return;
        const pubDate = (publishedAt ? new Date(publishedAt) : new Date()).toISOString();
        xml += `  <url>\n`;
        xml += `    <loc>${baseUrl}${pathPrefix}/${encodeURIComponent(canonicalSlug)}</loc>\n`;
        xml += `    <news:news>\n`;
        xml += `      <news:publication>\n`;
        xml += `        <news:name>${escapeXml(publicationName)}</news:name>\n`;
        xml += `        <news:language>${language}</news:language>\n`;
        xml += `      </news:publication>\n`;
        xml += `      <news:publication_date>${pubDate}</news:publication_date>\n`;
        xml += `      <news:title>${escapeXml(title)}</news:title>\n`;
        xml += `    </news:news>\n`;
        xml += `  </url>\n`;
      };

      let written = 0;
      const writeIfRoom = (fn: () => void) => {
        if (written >= NEWS_SITEMAP_TOTAL_LIMIT) return;
        fn();
        written++;
      };
      for (const a of arRecent) {
        writeIfRoom(() => writeNewsEntry(a.englishSlug || a.slug, '/article', a.title || '', a.publishedAt, 'صحيفة سبق الإلكترونية', 'ar'));
      }
      for (const a of enRecent) {
        writeIfRoom(() => writeNewsEntry(a.englishSlug || a.slug, '/en/article', a.title || '', a.publishedAt, 'Sabq News', 'en'));
      }
      for (const a of urRecent) {
        writeIfRoom(() => writeNewsEntry(a.englishSlug || a.slug, '/ur/article', a.title || '', a.publishedAt, 'سبق نیوز', 'ur'));
      }

      xml += '</urlset>';

      (app as any).__sitemapNewsCache = { xml, ts: now };

      res.header('Content-Type', 'application/xml; charset=utf-8');
      res.setHeader('Cache-Control', 'public, max-age=180, s-maxage=180');
      res.send(xml);
    } catch (error) {
      console.error("Error generating news sitemap:", error);
      res.status(500).send("Error generating news sitemap");
    }
  });

  // ============================================================
  // IndexNow Key Verification File
  // Search engines fetch /{key}.txt to verify domain ownership.
  // Must return exactly the key as plain text.
  // Only registered when INDEXNOW_KEY is configured (env-only).
  // ============================================================
  if (INDEXNOW_KEY) {
    app.get(`/${INDEXNOW_KEY}.txt`, (_req, res) => {
      res.setHeader('Content-Type', 'text/plain');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(INDEXNOW_KEY);
    });
  }

  // News Analytics Endpoint - Smart statistics and insights

  // Robots.txt. Per REP spec, the most-specific group wins per user-agent,
  // so we keep a single * group plus a Googlebot-News allow-list. Query-string
  // variants are handled via canonical + meta robots, not Disallow.
  app.get("/robots.txt", (_req, res) => {
    const robotsTxt = `# صحيفة سبق الإلكترونية — robots.txt
User-agent: *
Allow: /
Disallow: /api/

# ملاحظة: صفحات الحساب والمصادقة (login, register, logout, *-password,
# 2fa-verify, verify-email, profile, bookmarks, reading-history, my-*,
# notification-settings, recommendation-settings, select-interests,
# dashboard, admin, ifox, onboarding, payment) لم تَعُد محظورة هنا عمدًا.
# حظرها بـ robots.txt كان يُبقيها "مفهرسة رغم الحظر بواسطة robots.txt" في
# Search Console: لأن Google لا يستطيع زحفها، فلا يرى وسم noindex ولا يُسقطها.
# الآن يستطيع زحفها ويرى X-Robots-Tag: noindex (يضيفه وسيط Cloudflare Pages
# لكل مسارات noindex — راجع functions/_middleware.js) فيُسقطها من الفهرس.
# /api/ يبقى محظورًا لأنه نقاط نهاية JSON (ليست HTML) ولا يمكن وسمها بـ noindex.

# Googlebot-News intentionally has NO separate group — a previous
# "Disallow: /" (with a few Allow exceptions) blocked it from the homepage
# and section/category pages, which is where Google News discovers new
# articles. With no group of its own it falls back to "User-agent: *" above
# and can crawl everything public (articles + sections), which is what we want.

Sitemap: https://sabq.org/sitemap.xml
Sitemap: https://sabq.org/sitemap-news.xml
`;

    res.header('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Cache-Control', 'public, max-age=86400');
    res.send(robotsTxt);
  });

  // News Analytics Endpoint - Smart statistics and insights

