  // News Analytics Endpoint - Smart statistics and insights

  // GET Single English Article by Slug - with full details
  app.get("/api/en/articles/:slug", async (req: any, res) => {
    try {
      const userId = req.user?.id;
      const slug = req.params.slug;

      // Cache the heavy joined article + counts query (NOT user-specific) for 2 minutes
      const baseCacheKey = `en:article:base:${slug}`;
      const baseData = await withCache(baseCacheKey, CACHE_TTL.SHORT, async () => {
        const reporterAlias = aliasedTable(users, 'reporter');
        const results = await db
          .select()
          .from(enArticles)
          .leftJoin(enCategories, eq(enArticles.categoryId, enCategories.id))
          .leftJoin(users, eq(enArticles.authorId, users.id))
          .leftJoin(reporterAlias, eq(enArticles.reporterId, reporterAlias.id))
          .where(or(eq(enArticles.slug, slug), eq(enArticles.englishSlug, slug)))
          .limit(1);

        if (!results || results.length === 0) return null;
        const r: any = results[0];
        const art = r.en_articles;
        const [reactionsCountResult, commentsCountResult] = await Promise.all([
          db.select({ count: sql<number>`count(*)` }).from(enReactions).where(eq(enReactions.articleId, art.id)),
          db.select({ count: sql<number>`count(*)` }).from(enComments).where(eq(enComments.articleId, art.id)),
        ]);
        return {
          article: art,
          category: r.en_categories,
          authorData: r.users,
          reporterData: r.reporter,
          reactionsCount: Number(reactionsCountResult[0].count),
          commentsCount: Number(commentsCountResult[0].count),
        };
      });

      if (!baseData) {
        return res.status(404).json({ message: "Article not found" });
      }

      // Per-user lookups (small, fast, indexed) — only when authenticated
      let isBookmarked = false;
      let hasReacted = false;
      if (userId) {
        const [bookmarkResult, reactionResult] = await Promise.all([
          db.select().from(enBookmarks)
            .where(and(eq(enBookmarks.articleId, baseData.article.id), eq(enBookmarks.userId, userId)))
            .limit(1),
          db.select().from(enReactions)
            .where(and(eq(enReactions.articleId, baseData.article.id), eq(enReactions.userId, userId)))
            .limit(1),
        ]);
        isBookmarked = bookmarkResult.length > 0;
        hasReacted = reactionResult.length > 0;
      }

      // Fire-and-forget view increment (don't block response)
      db.update(enArticles)
        .set({ views: sql`${enArticles.views} + ${Math.floor(Math.random() * 6) + 5}` })
        .where(eq(enArticles.id, baseData.article.id))
        .catch(err => console.error("[EN article] view increment failed:", err));

      const displayAuthor = baseData.reporterData || baseData.authorData;
      const articleWithDetails: EnArticleWithDetails = {
        ...baseData.article,
        category: baseData.category || undefined,
        author: displayAuthor || undefined,
        isBookmarked,
        hasReacted,
        reactionsCount: baseData.reactionsCount,
        commentsCount: baseData.commentsCount,
      };

      res.json(articleWithDetails);
    } catch (error) {
      console.error("Error fetching EN article:", error);
      res.status(500).json({ message: "Failed to fetch article" });
    }
  });

  // Content Passport (Digital Fingerprint) — English
  app.get(
    "/api/en/articles/:slug/passport",
    async (req, res) => {
      try {
        const slug = req.params.slug;
        const viewerIsStaff = isStaffRole((req.user as any)?.role);
        res.setHeader("Vary", "Cookie, Authorization");
        if (viewerIsStaff) {
          res.setHeader("Cache-Control", "private, no-store");
        } else {
          res.setHeader(
            "Cache-Control",
            "public, max-age=300, s-maxage=600, stale-while-revalidate=300",
          );
        }
        const cacheKey = `article:passport:en:${slug}:${viewerIsStaff ? "s" : "p"}`;
        const passport = await withCache(cacheKey, CACHE_TTL.SHORT, async () => {
          return await buildEnglishPassport(slug, viewerIsStaff);
        });
        if (!passport) {
          return res.status(404).json({ message: "Passport not available" });
        }
        res.json(passport);
      } catch (error) {
        console.error("Error fetching EN article passport:", error);
        res.status(500).json({ message: "Failed to fetch passport" });
      }
    },
  );

