  // PATCH /api/publisher/articles/:id - Edit draft article
  // FIXED: Now uses secure updatePublisherArticle with ownership and status checks
  app.patch("/api/publisher/articles/:id", 
    requireAuth,
    async (req: any, res) => {
    try {
        const publisher = await getPublisherForUser(req.user.id);
        if (!publisher) {
          return res.status(404).json({ message: "لم يتم العثور على حساب الناشر" });
        }
        
        if (!publisher.isActive) {
          return res.status(403).json({ message: "حساب الناشر معطل" });
        }
        
        // Get article for logging (pre-update state)
        const article = await storage.getArticleById(req.params.id);
        
        // Mass-assignment guard: a publisher is a lower-trust external user
        // editing their OWN draft. Restrict to real article columns and strip
        // ownership/promotion/counter columns they must never control
        // (forging authorship, self-promoting to featured/breaking, inflating
        // views, back-dating publish, reordering the homepage). status is
        // force-set to draft below regardless of input.
        const updateData: any = {
          ...pickTableColumns(articles, req.body, {
            omit: [
              "authorId", "submitterId", "reporterId",
              "newsType", "isFeatured", "views",
              "publishedAt", "displayOrder", "hideFromHomepage",
            ],
          }),
          status: 'draft' as const, // Ensure it stays draft
        };
        
        // Convert empty thumbnailUrl to null (for proper deletion)
        if (updateData.thumbnailUrl === "") {
          updateData.thumbnailUrl = null;
        }
        
        // CRITICAL: Use secure storage method that verifies:
        // 1. Publisher owns the article (userId matches authorId)
        // 2. Article is still in draft status
        // Both checks are done at storage layer for defense in depth
        const updatedArticle = await storage.updatePublisherArticle(
          req.params.id,
          publisher.id,
          req.user.id,
          updateData
        );
        
        // Log activity (only if update succeeded)
        await logActivity({
          userId: req.user.id,
          action: 'update',
          entityType: 'article',
          entityId: updatedArticle.id,
          oldValue: article as any,
          newValue: updateData as any,
        });
        
        // Invalidate cache and broadcast to all connected clients for instant update
      invalidatePublishedContent({ reason: "article-write" });
      memoryCache.delete('lite-feed'); // Clear mobile app feed cache
      memoryCache.invalidatePattern('^article:detail:');
      memoryCache.invalidatePattern('^article:id:');
      memoryCache.invalidatePattern('^articles:');
      memoryCache.invalidatePattern('^sidebar:');
      console.log(`[Breaking News] Cache invalidated and SSE broadcast sent for article ${req.params.id}`);

      res.json(updatedArticle);
      } catch (error: any) {
        console.error("Error updating article:", error);
        
        // Handle specific security errors with clear messages
        if (error.message?.includes('غير مسموح')) {
          return res.status(403).json({ message: error.message });
        }
        if (error.message?.includes('المقال غير موجود')) {
          return res.status(404).json({ message: error.message });
        }
        if (error.message?.includes('يمكن تعديل المقالات في حالة المسودة')) {
          return res.status(403).json({ message: error.message });
        }
        if (error.name === 'ZodError') {
          return res.status(400).json({ message: "بيانات غير صحيحة", errors: error.errors });
        }
        
        res.status(500).json({ 
          message: "فشل في تحديث المقال",
          error: error.message 
        });
      }
    }
  );

